insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","Apply: Fees are payable before the inspection is scheduled; no minimum number of days is stated.","How to apply: Fill out the Application for a Certificate of Continued Occupancy (Code Enforcement page, Documents) and submit it with the fee to the Construction & Code Enforcement Office, 500 Mill Road, Absecon, NJ 08201. Fees are non-refundable and must be paid before the inspection is scheduled. Also file the Certification for Resale (smoke/CO/extinguisher) form.","Valid for: The application expires six months from the date received.","Inspection for compliance with the City property maintenance code (Chapter 266; the form cites the 1990 BOCA Property Maintenance Code)","Smoke alarms on every level (basement, first and second floors) and outside each separate sleeping area","Carbon monoxide alarms by every separate sleeping area","Portable fire extinguisher within 10 feet of the kitchen, in the exit path, visible, top no more than 5 feet above the floor, mounted on the maker's hanger or bracket","Extinguisher at least 2A:10B:C and no more than 10 lb, with owner's manual or instructions","Extinguisher serviced and tagged by a DCA-certified contractor within the past 12 months, or a recent purchase receipt"]$j$::jsonb, $j$[{"label":"CCO inspection, single-family residence (includes initial inspection and one re-inspection)","amount":"$75"},{"label":"Each additional re-inspection, starting with the third inspection (payable before scheduling)","amount":"$35"},{"label":"Certification of Smoke Alarm, CO Alarm and Portable Fire Extinguisher Compliance (1-2 family)","amount":"$75"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/code-enforcement/","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/construction/","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Chapter 160 of the Code of Absecon requires all properties having a change in owner, tenant or occupant receive a certificate of continuing occupancy stating the property is in compliance with the Chapter 266, property maintenance code. Residential properties must also comply with N.J.A.C.5:70-2.3 for smoke alarms, co alarms and fire extinguisher.$t$, $t$2dc6af9c6dd3c94b1e51609de431e80a7df4972a5adfedc4ab254f6be2480c43$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office (resale smoke/CO/extinguisher certification) (town fire bureau)","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","How to apply: Complete the Certification for Resale form (owner or authorized representative inspects and certifies), have it notarized, give the email address the certificate should go to, and submit it with the $75 fee to the City of Absecon Municipal Complex, 500 Mill Road (Code Enforcement, ext. 113).","Fire official in the NJ state directory, updated 2/6/2026: Tom Flynn · (609) 646-7382 · tflynn@abseconnj.org","Owner self-certification, signed before a notary, on the City's Certification for Resale form","Built 1978 and before: 10-year sealed battery smoke alarms on each level and outside each sleeping area","Built 1979 to 1987: AC-powered alarms near each sleeping area and in the basement, plus 10-year sealed battery alarms on each other level","Built 1987 to 1991: AC-powered, interconnected alarms on each level and outside each sleeping area","Built 1991 to present: AC-powered interconnected alarms with battery backup in all bedrooms, outside each sleeping area and on every level","Carbon monoxide alarm near the sleeping area(s), UL 2034 listed","Portable fire extinguisher, 2.5 to 10 lb ABC dry chemical, within 10 feet of the kitchen, mounted no higher than 5 feet and visible (2020 form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certification of Smoke Alarm, CO Alarm and Portable Fire Extinguisher Compliance (1-2 family)","amount":"$75"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://abseconnj.gov/fire-prevention/","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Application for One and Two Family Dwelling Certification of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance$t$, $t$86d584f0c99bad10c1ca91c8034df8b4c9628c3927ae4594115af25b49321600$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0102$t$, $t$Atlantic City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Permit (Certificate of Occupancy)$t$, $j$["Issued by: Atlantic City Department of Licensing & Inspections","Contact: Dale L. Finch, Director of Licensing & Inspections · 609-347-5290","How to apply: Apply online with the City's GovPilot Occupancy Permit Application (choose the Sale application type, give the closing date and buyer details, and attach the Certificate of Land Use, smoke certification and pest certification). Questions go to the Licensing & Inspection Department, City Hall, 1301 Bacharach Blvd., 5th Floor, Suite 502.","Certificate of Land Use (zoning) from Planning, (609) 347-5404, or the CRDA Tourism District, (609) 347-0500","Smoke certification from Fire Prevention (single-family or duplex)","Pest certification: report from a licensed exterminator that the unit is free of bed bugs, other insects and rodents","All utilities turned on for the inspection","No rubbish, debris or bulk garbage left on the property before the new occupancy","Buyer details (and all members or principals if the buyer is an LLC, corporation or partnership)","Also: Certificate of Land Use (zoning): Required attachment for the Occupancy Permit. Contact Planning, (609) 347-5404, or the CRDA Tourism District, (609) 347-0500.","Also: Pest certification: Certified examination report from a licensed exterminator that the unit is free of bed bugs, other insects and rodents; required attachment for the Occupancy Permit."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://main.govpilot.com/web/public/efeba3a1-0cd_Occupancy-Permit-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0$t$, $t$https://www.acnj.gov/departments/licensing-and-inspection$t$, $j$[{"url":"https://www.ecode360.com/15210509","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/efeba3a1-0cd_Occupancy-Permit-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.acnj.gov/api/data/GetPageContactInfo?tag=Licensing%20%26%20Inspection","label":"Official source (acnj.gov)"},{"url":"https://www.acnj.gov/departments/licensing-and-inspection","label":"Official source (acnj.gov)"}]$j$::jsonb, $t$The owner of any residential property shall obtain an occupancy permit prior to the sale of such property involving a new occupancy of any unit of dwelling space, provided that no occupancy permit shall be required for the sale of vacant properties, but shall be required prior to such time as a new occupancy occurs.$t$, $t$fcdf3f6b512892acd370e1ab16349392e3a9e64585f3ce0364443c0a2f0d5b6b$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":13,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0102.json$t$, true),
  ($t$0102$t$, $t$Atlantic City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Atlantic City Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Kevin Munn, Fire Official (state fire directory) · 609-347-5595 · kmunn@acnj.gov","Apply: Fee depends on timing: 10 or more days, 4 to 10 days, or under 4 days before the change of occupant. The inspection is scheduled only after payment.","How to apply: Submit the City's online GovPilot Smoke Detector Application and attach the Smoke Certificate Affidavit, filled out and notarized. Pay by check to the City of Atlantic City, cash or money order. Fees are non-refundable and an inspection cannot be scheduled until payment is made. Office: City Hall, 1301 Bacharach Blvd, Room 130.","Fire official in the NJ state directory, updated 1/27/2026: Kevin Munn · (609) 347-5595 · kmunn@acnj.gov","Notarized owner affidavit (Smoke Certificate Affidavit) attached to the online application","10-year sealed battery smoke alarm on each level, including basements (not attic or crawl space)","Smoke alarm and CO alarm outside each separate sleeping area, within 10 feet of it","Existing AC-powered or interconnected alarms in homes built after January 1977 must be kept working","Portable fire extinguisher 2A-10B:C, no more than 10 lb, on a hanger within 10 feet of the kitchen (2020 affidavit still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 10 days before change of occupant (per unit)","amount":"$45"},{"label":"Smoke/CO certificate, 4 to 10 days before change of occupant (per unit)","amount":"$70"},{"label":"Smoke/CO certificate, less than 4 days before change of occupant (per unit)","amount":"$125"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/60ccced5-73b_Smoke-Detector-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0$t$, $t$https://www.acnj.gov/departments/fire-prevention$t$, $j$[{"url":"https://main.govpilot.com/web/public/60ccced5-73b_Smoke-Detector-Application-atlanticcity?uid=6910&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.acnj.gov/_Content/pdf/forms/Smoke-Certificate-Affidavit.pdf","label":"Official source (acnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.acnj.gov/api/data/GetPageContactInfo?tag=Fire%20Prevention","label":"Official source (acnj.gov)"}]$j$::jsonb, $t$The Compliance Certificate must be filled out, notarized and attached with this application.$t$, $t$51dc268b30f781ee15cc4c3cb05345e5054f915d9375a6ebe5df0c9743a07a58$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":13,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0102.json$t$, true),
  ($t$0103$t$, $t$Brigantine$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Land Use Compliance$t$, $j$["Issued by: City of Brigantine Construction Office (Construction Official or designee; Land Use Administrator)","Contact: Patrick Malia, Construction Official (Zoning Officer: Mark Coyne) · 609-266-7600 ext. 261 · construction@brigantinenj.gov","Apply: The City code says the Construction Official may inspect within five working days of the application and acts on a completed application within five working days (seen in search results of the code).","How to apply: Fill out the Application Certificate of Land Use Compliance (posted on the Construction Office page as 'Land Use Application rev.4.4.25') and file it with the $75.00 fee (check or cash) at the Construction Office, City Hall, 1417 West Brigantine Avenue, Brigantine, NJ 08203. Questions: (609) 266-7600 ext. 261 or construction@brigantinenj.gov. The certificate does not replace a building permit.","Application for Certificate of Land Use Compliance (owner, applicant, block and lot, present and proposed use)","Land Use Administrator review of zoning classification and permitted use (single family, townhouse, approved conditional or existing non-conforming use), open permits or violations (NOP/NOV) and flood zone","Possible inspection of the house by the Construction Official or designee","Smoke/CO alarm certificate from the Bureau of Fire Prevention (separate, see fire certificate)","Also: Water/sewer special reading for sale: Request a special water reading with the Water Reading Request form (email taxcollector@brigantinebeachnj.com); allow 5 business days; $60.00 charge for a sale, collected at settlement by separate check. Quote: 'Based on Ordinance #20 pr 2022: there is a $60.00 charge for this special reading for the sale of a property.'","Also: Lead service line proof (possible): Search results for the City code (Lead Service Line Replacement article, Ord. No. 23-2022) say that on the sale or transfer of a dwelling the owner must show the lead service line was replaced, or a completed right of entry form for the City's replacement program, to get a certificate of occupancy, certificate of land use compliance and smoke/CO certificates. Seen only in search results; confirm with the City."]$j$::jsonb, $j$[{"label":"Certificate of Land Use Compliance (City fee ordinance)","amount":"$75.00"},{"label":"Certificate of Land Use Compliance (application form)","amount":"$75.00"}]$j$::jsonb, $t$https://brigantinebeach.org/wp-content/uploads/Land-Use-Application-rev.4.4.25-2.pdf$t$, $t$https://brigantinebeach.org/municipal/departments/construction-office/$t$, $j$[{"url":"https://brigantinebeach.org/wp-content/uploads/Land-Use-Application-rev.4.4.25-2.pdf","label":"Official source (brigantinebeach.org)"},{"url":"https://ecode360.com/7165345","label":"Official source (ecode360.com)"},{"url":"https://brigantinebeach.org/wp-content/uploads/12-3-25-meeting-minutes.pdf","label":"Official source (brigantinebeach.org)"},{"url":"https://brigantinebeach.org/wp-content/uploads/Chapter-198-Land-Use-04-10-25.pdf","label":"Official source (brigantinebeach.org)"},{"url":"https://brigantinebeach.org/municipal/departments/construction-office/","label":"Official source (brigantinebeach.org)"}]$j$::jsonb, $t$PER CITY OF BRIGANTINE CHAPTER 134 A certificate of land use compliance shall be required prior to the sale or any other type of transfer of title of any structure in the City of Brigantine, including but not limited to any time-sharing unit.$t$, $t$363e48e19ab550e65b450e0851348a3ea7b4f4b0e9780964d0db484e29e1ca89$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-07","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0103.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-07. Source: property/data/municipal-requirements/checked/0103.json$t$, true),
  ($t$0103$t$, $t$Brigantine$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Brigantine Bureau of Fire Prevention (town fire bureau)","Contact: Jack Murray, Fire Official · 609-266-3102 · fireprevention@brigantinebeachnj.com","Apply: Fee depends on when the application is submitted: 11 or more business days, 4 to 10 business days, or under 4 business days before settlement.","How to apply: Fill out the Bureau of Fire Prevention Request for Inspection form, check 'Smoke Detector/CO (Sale)', and give the settlement date, realty office, agent contact, property details and access (key, lock box or door code). Send it by email to Fireprevention@brigantinebeachnj.com or fax 609-266-0291, or bring it to 1417 W Brigantine Avenue. The form records payment by check or cash.","Fire official in the NJ state directory (NJ DCA, state), updated 5/16/2025: Louis Kilmer · (609) 633-6132","Request a Smoke Detector/CO (Sale) inspection; the form asks for number of bedrooms and bathrooms, heat, water heater and stove fuel, fireplace and garage","Property access for the inspector (key, lock box number or door code) and occupant contact if occupied","Portable fire extinguisher: at least one, listed and charged, 2A:10B:C to 10 lb, on the maker's hanger or bracket, within 10 feet of the kitchen, top no more than 5 feet above the floor, visible, near an exit path, with owner's manual (posted 2005 DCA memo)","Fire extinguisher must have the original sales receipt (note on the posted memo)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, application 11 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, application 4 to 10 business days before settlement","amount":"$90.00"},{"label":"Smoke/CO certificate, application less than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://brigantinebeach.org/wp-content/uploads/20240830130803.pdf$t$, $t$https://brigantinebeach.org/municipal/departments/fire-prevention-bureau/$t$, $j$[{"url":"https://brigantinebeach.org/municipal/departments/fire-prevention-bureau/","label":"Official source (brigantinebeach.org)"},{"url":"https://brigantinebeach.org/wp-content/uploads/20240830130803.pdf","label":"Official source (brigantinebeach.org)"},{"url":"https://brigantinebeach.org/wp-content/uploads/12-3-25-meeting-minutes.pdf","label":"Official source (brigantinebeach.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Bureau of Fire Prevention Jack Murray Fire Official Phone: 609-266-3102$t$, $t$47eb483616baca211caa3270dff6bfd656c15f99df8f4dadcb0d62b01a59fe7c$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-07","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0103.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-07. Source: property/data/municipal-requirements/checked/0103.json$t$, true),
  ($t$0106$t$, $t$Corbin City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Corbin City. Confirm with the office if the buyer's lender or title company asks.","Contact: Alexander Bauer, Zoning Officer · 609-701-0203 · Zoning@corbincitynj.com","How to apply: No City resale certificate. The City's fact sheet says no documentation or inspections are required by the City to sell property; only the State smoke/CO certificate (and any county septic or well testing) applies.","Also: Septic inspection: The Atlantic County Health Department may require a septic inspection; call (609) 645-5971 x4371 to verify.","Also: Private well test: The well must be tested under the state Private Well Testing Act through a third-party vendor."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://sites.google.com/view/corbincitynj/municipal-services/zoningconstruction$t$, $j$[{"url":"https://drive.google.com/uc?export=download&id=1YSBEuVwDPovVS3IY5l5guotF43xcQ8Ru","label":"Official source (drive.google.com)"},{"url":"https://sites.google.com/view/corbincitynj/municipal-services/city-clerk/forms","label":"Official source (sites.google.com)"},{"url":"https://sites.google.com/view/corbincitynj/municipal-services/zoningconstruction","label":"Official source (sites.google.com)"}]$j$::jsonb, $t$Selling Property: The city does not require any documentation or inspections to sell property.$t$, $t$88cb45c1e45adc0f684871711b4050e53441b7aecafdd4dbc6c3d605d272f6a7$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0106.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0106.json$t$, true),
  ($t$0106$t$, $t$Corbin City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Fee depends on how many business days before the change of occupant the request is received (more than 10, 4 to 10, fewer than 4).","How to apply: Apply online through the NJ DCA Fire Safety portal ('Start Your Smoke Certification Application'): give the application date, reason (change of ownership or change of occupancy), closing date, property block, lot and address, and pay the application fee online. Homes heated by electricity with no CO alarm requirement should also email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 7/22/2026: Louis Kilmer · (609)633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate, request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"State smoke/CO certificate, request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"State smoke/CO certificate, request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://drive.google.com/uc?export=download&id=1YSBEuVwDPovVS3IY5l5guotF43xcQ8Ru","label":"Official source (drive.google.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The smoke detector and/or carbon monoxide detector system must be inspected (CSDCMAC Certification) through the NJ Division of Fire Safety. You must schedule this inspection online at: https://firesolutions.dca.nj.gov/$t$, $t$2fd4e46d4582743bde24362e9741986450ca83191c45fa7d253365698c9d2796$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0106.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0106.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Transfer Certificate (Occupancy Transfer Inspection)$t$, $j$["Issued by: Egg Harbor City Code Enforcement Officer (applications go to the City Construction Office / Building Department)","Contact: Donna Heffley, Land Use and Building Department Office Manager · 609-965-1616 · donnah@eggharborcity.org","How to apply: Download the Occupancy Transfer Inspection Form from Forms & Documents, mark it SALE, and submit it with the Smoke and Carbon Monoxide Alarm Certificate Application to the Egg Harbor City Construction Office, 500 London Ave., Egg Harbor City, NJ 08215 ($75.00 per unit). Pay with exact cash, money order or check made out to City of Egg Harbor City, or online through the City's WIPP portal (2.95% fee).","Occupancy transfer certificate needed before a dwelling is sold, transferred or rented (City Code Section 213-6H, PM-107.6)","Inspection covers cleanliness, walls and ceilings, doors and hardware, windows, storm windows and screens, exterior paint and maintenance, a visual roof check, basement, kitchen, bathrooms, smoke detectors, carbon monoxide detector, electrical outlets, switches, covers and fuse box cover, sidewalks, lawn, shrubs and trees, maximum bedroom occupancy and all City code, zoning and planning ordinances","Submit the Smoke and Carbon Monoxide Alarm Certificate Application together with the Occupancy Transfer Inspection form","Form asks for owner, purchaser, tenant and lock box details and the building type, bedrooms, heat, sewer/septic and water/well"]$j$::jsonb, $j$[{"label":"Occupancy transfer certificate inspection, per dwelling unit (covers the first inspection and one follow-up)","amount":"$75"},{"label":"Each additional inspection after one follow-up","amount":"$25"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://ecode360.com/8035021","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8032087","label":"Official source (ecode360.com)"},{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsResources?tn=eggharborcityorg&et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&pi=TToDIgI7usSeZfigcPBGFg%3d%3d&eb=KpjeAhPgzh3BNBSf%252BZdFBg%3d%3d&tg=YihSMzUNwfZ0WRShR9VMgw%3d%3d&xtg=","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"}]$j$::jsonb, $t$No owner or leaseholder or his agent shall rent, sell, transfer, grant, lease, let, mortgage with right of occupancy or otherwise dispose of the ownership or occupancy$t$, $t$fdfee297e4ecfd57c94748945d7f5d190c5ce6352e10a159999d484c73fe97bc$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":4,"fee_unchecked":2,"quotes":15,"q_ok":6,"q_bad":4,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Egg Harbor City Fire Official (Fire Marshal), Fire Prevention (town fire bureau)","Contact: Stephen Buchhofer, Fire Marshal (also Construction Official and Electric, Plumbing, Fire & Mechanical Subcode Official) · 609-965-0081 · EHCFirePrevention@eggharborcity.org","Apply: Fee depends on how many days before the Certificate of Occupancy must be issued: more than 10 days, 4 to 10 days, or fewer than 4 days. Inspections are available Tuesdays and Thursdays from 2 to 6 pm.","How to apply: Fill out the Smoke and Carbon Monoxide Alarm Certificate Application (Forms & Documents) and submit it with the Occupancy Transfer Inspection form to the City, 500 London Ave., Egg Harbor City, NJ 08215. Questions: EHCFirePrevention@eggharborcity.org. After a failed reinspection the process starts over with a new fee.","Fire official in the NJ state directory, updated 1/27/2026: Stephen Buchhofer · (856) 656-5456 · swb6203@comcast.net","10-year sealed battery smoke alarm in every bedroom (depending on construction year)","Basement smoke alarm at the bottom of the stairwell at ceiling level (not between joists)","Hallway smoke alarms within 10 feet of all bedroom doors","Electric smoke alarms required by the building code cannot be replaced with battery alarms","Smoke detectors at least 3 feet from ceiling fan blade tips and air ducts; none in kitchens, bathrooms, dead air space, crawl spaces or attics","CO alarm in the hallway within 10 feet of all bedrooms; not plugged into a switched outlet","Fire extinguisher: residential 2A:10B:C, no larger than 10 lb, mounted within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, requested more than 10 days before the certificate is needed (per unit)","amount":"$55"},{"label":"Smoke/CO inspection, requested 4 to 10 days before the certificate is needed (per unit)","amount":"$90"},{"label":"Smoke/CO inspection, requested fewer than 4 days before the certificate is needed (per unit)","amount":"$160"},{"label":"First reinspection when more than one follow-up inspection is needed","amount":"$50"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"},{"url":"https://www.eggharborcity.org/building","label":"Official source (eggharborcity.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Thereafter, the inspection process shall be considered to have recommenced with the fees of $55, $90, or $160 due depending upon the timing of the application as outlined above.$t$, $t$530bdfddf9ff9e4d76f775d78abf9d18dcc88a3536993dea6c289836684a5a9a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":4,"fee_unchecked":2,"quotes":15,"q_ok":6,"q_bad":4,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0108$t$, $t$Egg Harbor Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Egg Harbor Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Pat J. Naticchione, Construction Official · 609-926-4122 · BuildingInspections@ehtnj.gov","How to apply: No Township resale CO or CCO for residential sales. The only Township item for a home sale is the smoke detector / carbon monoxide certificate from the Bureau of Fire Inspections (see fire certificate)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.ehtnj.gov/departments/planning___development/building_inspections.php$t$, $j$[{"url":"https://www.ehtnj.gov/community/forms.php","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/Building/Fillable%20CCO%20letter.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/departments/planning___development/building_inspections.php","label":"Official source (ehtnj.gov)"}]$j$::jsonb, $t$EHT does NOT require CCO Inspections for residential resales or rentals.$t$, $t$6df7d502459bda15fcd009908700decd5a780e601a727f1fd05468a63aff8902$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0108.json$t$, true),
  ($t$0108$t$, $t$Egg Harbor Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Egg Harbor Township Bureau of Fire Inspections (town fire bureau)","Contact: Brian Cummings, Fire Official · 609-926-4070 · fireinspections@ehtnj.gov","Apply: Payments are not accepted after 4:15 pm.","How to apply: Download the 'Smoke Cert. - Property Resale / Residential Tenant' affidavit from the Document Center. Either fill out the whole form as a notarized owner affidavit, or fill out only the top portion to request an on-site inspection. Submit it with the fee to the Bureau of Fire Inspections, 3515 Bargaintown Road, Egg Harbor Township, NJ 08234 (fax 609-926-4181). Office hours Monday to Friday 8:30 am to 4:30 pm; no payments after 4:15 pm.","Fire official in the NJ state directory (town), updated 9/2/2025: Brian D Cummings · (609) 926-4070 · Bcummings@ehtgov.org","Built 1978 and before: 10-year sealed battery smoke alarms on each level and outside each separate sleeping area","Built 1979 to 1987: hard-wired alarms near each sleeping area and in the basement; 10-year sealed battery alarms can be added for the other levels","Built 1988 to 1991: hard-wired, interconnected alarms on each level and outside each sleeping area","Built 1991 to present: hard-wired interconnected alarms with battery backup in all bedrooms, outside each sleeping area and on every level","Carbon monoxide alarm near the sleeping area(s), UL 2034 listed","Choice of a notarized owner affidavit or an on-site inspection request","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke Detector Application","amount":"$54.00"},{"label":"Second fee amount printed on the affidavit form (timing tier not labeled on the form)","amount":"$90"},{"label":"Third fee amount printed on the affidavit form (timing tier not labeled on the form)","amount":"$161"}]$j$::jsonb, $t$https://www.ehtnj.gov/2025affidavit9.9.25.pdf$t$, $t$https://www.ehtnj.gov/departments/planning___development/fire_inspections.php$t$, $j$[{"url":"https://www.ehtnj.gov/departments/planning___development/fire_inspections.php","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/2025affidavit9.9.25.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/Building/Fillable%20CCO%20letter.pdf","label":"Official source (ehtnj.gov)"},{"url":"https://www.ehtnj.gov/departments/planning___development/index.php","label":"Official source (ehtnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official: Brian Cummings Fire Inspectors: Craig Thompson & Ray Conover Office Staff: Tammy Naylor, Clerk 1$t$, $t$8048be7491f8c345aa13688e6bdecc2d27e849fa02f4083a4204d7d5810e3076$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0108.json$t$, true),
  ($t$0109$t$, $t$Estell Manor$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale (Housing Officer's certificate of occupancy inspection)$t$, $j$["Issued by: City of Estell Manor Housing Officer / Housing Inspector","Contact: Chase Farabella, Housing Inspector (also Zoning Officer and Code Enforcement) · 609-476-2692 ext. 104 · zoning@estellmanor.org","How to apply: Fill out the City's Certificate of Occupancy Application, tick 'Certificate of Occupancy - Sale', list the settlement date and a contact person to set up the appointment, and submit it to the Housing Inspector at 148 Cumberland Avenue, Estell Manor, NJ 08319 with the $50.00 fee payable to the City of Estell Manor. The smoke/CO certificate is a separate application through the NJ DCA portal.","Certificate of occupancy whenever ownership or tenancy of a dwelling changes (City Code Section 380-72D(4))","Owner must open the home to inspection by the Housing Officer at reasonable hours","Give the settlement date and a contact person to set up the appointment on the application","State smoke/CO certificate is a separate application through the NJ DCA portal"]$j$::jsonb, $j$[{"label":"Certificate of occupancy for resale or rerental (with smoke detector certificate)","amount":"$50"},{"label":"Second or more reinspection for certificate of occupancy, per unit","amount":"$30"}]$j$::jsonb, $t$http://www.estellmanor.org/images/new_co_chase.pdf$t$, $t$http://www.estellmanor.org/departments.html$t$, $j$[{"url":"https://ecode360.com/29978921","label":"Official source (ecode360.com)"},{"url":"http://www.estellmanor.org/images/new_co_chase.pdf","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/formslinks.html","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/contactus.html","label":"Official source (estellmanor.org)"},{"url":"http://www.estellmanor.org/departments.html","label":"Official source (estellmanor.org)"},{"url":"https://ecode360.com/29976480","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Change of tenancy or ownership. From and after the effective date of this chapter, a certificate of occupancy shall be required whenever there is a change in ownership or tenancy of any building or structure used for dwelling purposes.$t$, $t$ef910c0c05be0faa80942a22ef5bf107a2ddcfdef3e3bd93ad76dcc7afbcbe36$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":17,"q_ok":7,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0109.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0109.json$t$, true),
  ($t$0109$t$, $t$Estell Manor$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6132 · BFCECodeAdmin@dca.nj.gov","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal (Apply Smoke Certification). The City's instructions: complete the Smoke Cert data, submit, pay, and wait for the status 'Approved-Pending Inspection'. For help email BFCECodeAdmin@dca.nj.gov or call 609-633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 1/27/2026: Louis Kilmer · (609)633-6132","Smoke alarms, carbon monoxide alarms and, for homes with solar, generators or batteries, a secondary power source identification label (the State application is now the CSACMASPSIL)","The City's CO form (August 2025) still describes the state certificate as covering a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Requested more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Requested 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Requested fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://www.estellmanor.org/images/new_co_chase.pdf","label":"Official source (estellmanor.org)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Estell Manor City$t$, $t$9bab71a32a2f058f3ab73bdb43017992c04b6f296e0a6bc94d94f5552df622a0$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":17,"q_ok":7,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0109.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0109.json$t$, true),
  ($t$0110$t$, $t$Folsom Borough$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough Zoning Official (Frank Sacco, Zoning/Code Enforcement Official)","Contact: Frank Sacco, Zoning/Code Enforcement Official · 609-561-3178 · fsacco@folsomborough.com","How to apply: Contact the Borough Zoning Official, Frank Sacco, at Borough Hall (1700 Rt 54, Folsom, NJ 08037) to request the certificate of continued occupancy and pay the $25 fee. He holds office hours Mondays 5:00 to 7:00 PM. The Borough code does not publish a form, a lead time or the exact sale trigger, so call ahead to confirm.","Property must meet the Borough Property Maintenance Code (Chapter 151)","Rental units: a current CCO must be attached to the Borough landlord registration (Chapter 152)"]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy","amount":"$25"}]$j$::jsonb, null, $t$https://folsomborough.com/services/construction.asp$t$, $j$[{"url":"https://ecode360.com/10063291","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/38657679","label":"Official source (ecode360.com)"},{"url":"https://folsomborough.com/services/construction.asp","label":"Official source (folsomborough.com)"},{"url":"https://folsomborough.com/government/directory.asp","label":"Official source (folsomborough.com)"}]$j$::jsonb, $t$The following fees in this article are under the jurisdiction of the Zoning Official but are not applicable to the uniform construction codes.$t$, $t$6624014d94cbcf8e888c9e74dcaf9585c86ffb3149b9d4dedbec970dd1d73084$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0110.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0110.json$t$, true),
  ($t$0110$t$, $t$Folsom Borough$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6132 · BFCECodeAdmin@dca.nj.gov","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal (Apply Smoke Certification), as the Borough's Construction Office page directs. Pay online before submitting; a valid email address is required. For help email BFCECodeAdmin@dca.nj.gov or call 609-633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 7/26/2025: Louis Kilmer · (609)633-6132","Smoke alarms, carbon monoxide alarms and, for homes with solar, generators or batteries, a secondary power source identification label (the State application is now the CSACMASPSIL)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Requested more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Requested 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Requested fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://folsomborough.com/services/construction.asp","label":"Official source (folsomborough.com)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Folsom Borough$t$, $t$0e8cdcea886fba56f18cc8b0016b17dfff1a16198688ff7bea910e82f8cf083e$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0110.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0110.json$t$, true),
  ($t$0115$t$, $t$Longport Borough$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Land Use Compliance Certificate for a property sale (Certificate of Occupancy and/or Land Use Compliance Certificate)$t$, $j$["Issued by: Borough of Longport Building and Zoning Department","Contact: 609-823-2731 ext. 108, 109 or 120 · building@longport-nj.us","How to apply: Complete the 'Application for Land Use Compliance of a Property for Sale' (Housing section of the Borough forms page) with the settlement date, a point of contact and access details (door code, lock box or key), and submit it with the $150.00 fee, a current site survey, a flood elevation certificate, the sales contract or proof of sale price, and Form 1A for the smoke detector certificate to the Building and Zoning Department, 2305 Atlantic Avenue, Longport, NJ 08403. The Building Department inspects and then issues the certificate.","Inspection by the Building Department before the certificate is issued","Dwelling must comply with federal, state and local housing codes and be kept safe and sanitary with proper light and ventilation (Borough Chapters 108, 110 and 136)","Open permit review by the office (copy to the Tax Assessor)","Submit a current site survey, a flood elevation certificate, the sales contract or proof of sale price, and Form 1A (smoke detector certificate application) with the application","Also: Current site survey: Required with the Land Use Compliance application for a sale.","Also: Flood elevation certificate: Required with the application.","Also: Sales contract, proof of sale price or interest conveyed: Required with the application.","Also: Open permit review: The office checks for open permits and sends a copy to the Tax Assessor."]$j$::jsonb, $j$[{"label":"Land Use Compliance application for a sale","amount":"$150.00"}]$j$::jsonb, $t$https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf$t$, $t$https://www.longportnj.gov/Departments/building-construction$t$, $j$[{"url":"https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf","label":"Official source (longportnj.gov)"},{"url":"https://www.longportnj.gov/api/data/GetFormsData","label":"Official source (longportnj.gov)"},{"url":"https://www.longportnj.gov/api/data/GetDirectoryDepartmentsData","label":"Official source (longportnj.gov)"},{"url":"https://ecode360.com/LO0700","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Application for Land Use Compliance of a Property for Sale$t$, $t$29785c071484db5ff29d5955f913d4d73d475f571f20f60e08b4ddf13935205a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":15,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0115.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0115.json$t$, true),
  ($t$0115$t$, $t$Longport Borough$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Longport Bureau of Fire Prevention (town fire bureau)","Contact: Levon S Clayton, Fire Official (state fire directory) · 609-822-9578 · firechief@longport-nj.us","How to apply: Complete Form 1A (Application for Certificate of Smoke Detector Compliance) in the Borough sale packet and submit it with the Land Use Compliance application. The Longport Fire Official inspects by appointment only. Pay by check only, payable to Longport Bureau of Fire Prevention; no certificate is issued before the fee is paid.","Fire official in the NJ state directory (town), updated 6/25/2026: Levon S Clayton · (609) 822-9578 · firechief@longport-nj.us","Smoke alarms on each level, in every bedroom, and outside each sleeping area within 10 feet of doorways","Since January 1, 2019: 10-year sealed lithium battery single-station smoke alarms (ANSI/UL 217); existing AC-powered alarms are accepted and must not be removed","Carbon monoxide alarms on each level and in the immediate vicinity of all sleeping areas","Central-station monitored alarm systems must be inspected by a NJ certified fire protection contractor, with the report available at the fire inspection","Owner, agent or designee must be present; detectors mounted more than 9 feet up must be tested by the owner or agent","A penalty of up to $500.00 may apply if the sale closes before the certificate is received","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Detector Compliance application","amount":"$75.00"},{"label":"Each reinspection","amount":"$30.00"}]$j$::jsonb, $t$https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf$t$, $t$https://www.longportnj.gov/Departments/volunteer-fire-department$t$, $j$[{"url":"https://www.longportnj.gov/_Content/pdf/forms/Sale-Application.pdf","label":"Official source (longportnj.gov)"},{"url":"https://www.longportnj.gov/api/data/GetDirectoryDepartmentsData","label":"Official source (longportnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Form “1A” to be completed in addition to the Land Use Compliance Form.$t$, $t$cc2737b485105c8d5b7a5b737514895d24ede4717fed995da14329bbb4397f89$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":15,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0115.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0115.json$t$, true),
  ($t$0116$t$, $t$Margate City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale / Land Use Certificate (Transfer of Title Certificate)$t$, $j$["Issued by: City of Margate City Department of Building Inspection (Construction Code Official)","Contact: Dino Cavalieri, Construction Official · 609-822-1974 · margate_inspection@margate-nj.com","Apply: Before closing","How to apply: Complete the Resale/Land Use Certificate Application (Title Transfers) with seller, agent and buyer details, the person to meet the inspector and the settlement date, and submit it with the $60.00 fee payable to the City of Margate (check, cash or card) to the Department of Building Inspection, 9001 Winchester Avenue, Margate City, NJ 08402 (margate_inspection@margate-nj.com). Then coordinate the inspection with the Building Department. Attach the Boca form for demolition or rehab if the buyer plans either.","Smoke alarms on each level, in every bedroom and outside each sleeping area within 10 feet of doorways","10-year sealed lithium battery smoke alarms (since January 1, 2019); existing AC-powered alarms accepted, do not remove","Carbon monoxide alarms on each level and outside sleeping areas","GFCI outlets at kitchen and bathroom counters, within 6 feet of a utility sink or wet bar, and in garages and outdoors","Portable fire extinguisher (2A-10B:C, 10 lb max) within 10 feet of the kitchen, on its bracket, top no higher than 5 feet, with the manual left for the new occupant (checklist still lists it)","No open permits (checked by the office)","No dwelling can be occupied until the certificate is issued","Also: Open permits: The resale application's office section records 'No Open Permits' or lists open permits and the date closed.","Also: Boca form for demolition or rehab: Attach the Boca Form for Demo or Boca Form for Rehab if the property will be demolished or rehabilitated."]$j$::jsonb, $j$[{"label":"Resale/Land Use Certificate application","amount":"$60.00"}]$j$::jsonb, $t$https://www.margate-nj.com/DocumentCenter/View/4584/2024-Application-for-Resale-Land-Use-Approval-Fillable$t$, $t$https://www.margate-nj.com/1253/Rentals-and-Resales-Housing-Forms-and-In$t$, $j$[{"url":"https://www.margate-nj.com/1253/Rentals-and-Resales-Housing-Forms-and-In","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4584/2024-Application-for-Resale-Land-Use-Approval-Fillable","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/1202/ConstructionBuilding-Department","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4755/Housing-Rental-and-Resale-Inspection-Requirements","label":"Official source (margate-nj.com)"}]$j$::jsonb, $t$Transfers of Title Certificates: To purchase or sell a property, a Land Use Certificate application must be completed before closing.$t$, $t$7ab8782029323d25f9119683f4c6c7e0a7b351e34250f397abcdb7d124f5965a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0116.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0116.json$t$, true),
  ($t$0116$t$, $t$Margate City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Margate City Department of Building Inspection (smoke detector compliance) / Margate City Fire Department (fire code enforcing agency) (town fire bureau)","Contact: Pat Baker, Fire Inspector (Building Department) · 609-822-2605 ext. 127 · margate_inspection@margate-nj.com","How to apply: The smoke, CO and extinguisher items are checked in the Building Department's rental and resale housing inspection. No separate smoke/CO certificate application or fee was found online; ask the Department of Building Inspection (609-822-1974) whether the $60.00 Resale/Land Use Certificate covers it.","Fire official in the NJ state directory, updated 5/26/2026: Daniel Adams · (609) 822-1974 · adams_dan@margate-nj.com","Smoke alarms on each level, in every bedroom and outside each sleeping area within 10 feet of doorways","10-year sealed lithium battery single-station smoke alarms since January 1, 2019; existing AC-powered alarms stay","Carbon monoxide alarms on each level and outside sleeping areas","Portable fire extinguisher 2A-10B:C, no more than 10 lb, within 10 feet of the kitchen in a path of egress, mounted on its bracket with the top no more than 5 feet above the floor; owner's manual left for the new occupant (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.margate-nj.com/1202/ConstructionBuilding-Department$t$, $j$[{"url":"https://www.margate-nj.com/1202/ConstructionBuilding-Department","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/DocumentCenter/View/4755/Housing-Rental-and-Resale-Inspection-Requirements","label":"Official source (margate-nj.com)"},{"url":"https://www.margate-nj.com/1333/Fire","label":"Official source (margate-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Pat Baker Fire Inspector 609-822-2605, ext. 127$t$, $t$7125b84f9b467f7125fdb14b8e64886618a33ea9d1526fc9233d3b2cc419597a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0116.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0116.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (Maintenance Code certificate)$t$, $j$["Issued by: Mullica Township Zoning and Code Enforcement Office (Code Officer)","Contact: Steven Hadley, Zoning Officer / Code Enforcement Official · 609-561-7070 x 133 · zoning@mullicatownship.org","How to apply: Download the Resale Certificate Application from the Township Forms page ('RESALE APPLICATION'). Fill in block, lot, zone, property address, lock box number and location, homeowner, buyer and realtor details, and return it with the $75.00 fee (cash or check), a copy of approved well and septic testing and, in a flood zone, the elevation certificate. The form does not say whether to mail, email or drop it off, so ask the office (609-561-7070 x 133, zoning@mullicatownship.org). The Township then schedules the inspection. The Zoning and Code Enforcement Officer works Tuesday, Wednesday and Thursday, 8:30 am to 4 pm; an appointment is recommended.","Township inspection; the certificate is marked passed or failed (inspection checklist not published)","Copy of approved well and septic testing submitted with the application","Copy of the elevation certificate if the home is in a flood zone","A conditional certificate is possible if the buyer acknowledges the violations and agrees to fix them within 90 days of the sale (Township code, seen in search results)","Also: Well and septic test results: A copy of approved well and septic testing is needed to process the resale certificate.","Also: Flood zone elevation certificate: A copy of the elevation certificate is needed if the home is in a flood zone.","Also: Construction permits: Since February 9, 2026 the Uniform Construction Code in Mullica is enforced by the NJ DCA Southern Regional Office (DCA SRO contact 609 567-3653), so open construction permits are handled there."]$j$::jsonb, $j$[{"label":"Resale certificate application","amount":"$75.00"}]$j$::jsonb, $t$https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf$t$, $t$https://www.mullicatownship.org/departments/development-housing/code-enforcement/$t$, $j$[{"url":"https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/forms/","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/departments/development-housing/code-enforcement/","label":"Official source (mullicatownship.org)"},{"url":"https://ecode360.com/9424366","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$RESALE CERTIFICATE APPLICATION$t$, $t$07df48d3bbf0d51786d65057d3e674ae701a44e5895c5bf225f35239e26135a4$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety service portal ('Start Your Smoke Certification Application'), choosing change of ownership, the closing date and the property location, and pay online. For questions call the Bureau of Fire Code Enforcement at (609) 633-6106.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","State certificate of smoke alarm and carbon monoxide alarm compliance from NJ DCA (state-enforced town)","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19; the portable fire extinguisher was dropped from the sale certificate by P.L.2025, c.19","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Mullica Township$t$, $t$a71da176049143bd0a8f421c758b65b192fdc1064281dec70b5156c88b877f7d$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0118$t$, $t$Northfield$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance for the Resale of One and Two Family Dwellings (CCO)$t$, $j$["Issued by: City of Northfield Housing Officer (Housing and Zoning)","Contact: 609-641-2832 ext 140 · housing@cityofnorthfield.org","Apply: Inspections are made within 10 business days of the application. If settlement is 5 days or less from the application, the City does not guarantee an inspection before closing and an extra $10 fee may apply.","How to apply: Download the 'Application for Certificate of Compliance for Residential Resale (CCO)' packet from the City Forms page, fill in block, lot, settlement date, year built, seller, agent and buyer, and give it to the Housing Officer, City Hall, 1600 Shore Road, Northfield, with the $85.00 non-refundable fee (checks payable to the City of Northfield) and the heating certification for oil or gas heat. Inspections are scheduled for Mondays only by calling 609-641-2832 ext 140 (housing@cityofnorthfield.org). If repairs are still open at closing, the buyer can sign the notarized 'Resale Certification of As-Is Conditions' form; the home cannot be occupied until a re-inspection passes and the Certificate of Compliance is issued.","Smoke alarms and carbon monoxide alarms in good working order, placed by the year the home was built (see fire certificate)","Portable ABC fire extinguisher near the kitchen (packet still lists it; see fire certificate)","Heating certification for every oil or gas fired heating unit, from a NJ licensed plumber or HVAC contractor","Sidewalks, walkways, stairs, driveways and parking areas in good repair","Yard free of weeds; garages, fences and other accessory structures sound","Pools clean; pools, hot tubs and spas over 24 inches deep fenced at least 48 inches high with self-closing, self-latching gates","Exterior wood painted or protected; house number plainly visible from the street","Roof, flashing, gutters and downspouts sound and draining properly","Windows that open can be held open; every habitable room has at least one openable window","Interior in good repair, sanitary, and free of rubbish or garbage","Bathroom window or mechanical exhaust vented outdoors","Heat provided; at least two outlets in each habitable room, a bathroom outlet, a laundry outlet, cover plates on all outlets, GFCI protection within 4 feet of water (if remodeled)","Fences, decks, sheds, pools and similar items built without zoning or construction permits delay the certificate until corrected","Also: Heating certification: Required for all oil and gas fired heating units, from a NJ licensed plumber or HVAC contractor.","Also: Unpermitted structures: Any fence, deck, shed, pool or similar item installed without zoning or construction permits delays the Certificate of Compliance until corrected or abated.","Also: Buying as-is: The buyer can sign a notarized Resale Certification of As-Is Conditions agreeing to make the repairs on the Conditional Certificate of Compliance; no occupancy until a re-inspection passes and the Certificate of Compliance is issued."]$j$::jsonb, $j$[{"label":"Resale CCO application and inspection, non-refundable","amount":"$85.00"},{"label":"Re-inspection due to violations","amount":"$25.00"},{"label":"Settlement 5 days or less after application (may apply)","amount":"$10"}]$j$::jsonb, $t$https://www.cityofnorthfield.org/pdf/RESALE-property-inspection-registration-packet-2026.pdf$t$, $t$https://www.cityofnorthfield.org/government/zoning.asp$t$, $j$[{"url":"https://www.cityofnorthfield.org/pdf/RESALE-property-inspection-registration-packet-2026.pdf","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/government/zoning.asp","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/pdf/Residential%20resale%20-%20certification%20of%20'as%20is'%20conditions.pdf","label":"Official source (cityofnorthfield.org)"},{"url":"https://www.cityofnorthfield.org/main/forms.asp","label":"Official source (cityofnorthfield.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF COMPLIANCE FOR THE RESALE OF ONE AND TWO FAMILY DWELLINGS (CCO)$t$, $t$77bcb779883b1cd3680fae61dbbd93cf4487dde0cee086357fd5b92b2b8be979$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0118.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0118.json$t$, true),
  ($t$0118$t$, $t$Northfield$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety service portal ('Start Your Smoke Certification Application'), choosing change of ownership, the closing date and the property location, and pay online. For questions call the Bureau of Fire Code Enforcement at (609) 633-6106. Also ask the City Housing Officer (609-641-2832 ext 140) whether the City's resale CCO inspection is accepted in place of, or in addition to, the state certificate.","Fire official in the NJ state directory (NJ DCA, state), updated 5/29/2025: Louis Kilmer · (609) 633-6132","Smoke alarms by year built (City packet): before January 1977 battery alarms on each level including the basement and within 10 feet of bedrooms; later homes A/C powered (hardwired), interconnected from August 1984, and from March 1991 A/C powered with battery backup on each level and inside each bedroom","Ten-year sealed battery single station smoke alarms where no alarms exist or when replacing battery alarms; hardwired alarms from original construction or a rehab project may not be replaced with battery alarms","Replace smoke alarms 10 years from manufacture or when they fail tests; replace combination smoke/CO alarms at the end-of-life signal or 10 years","Carbon monoxide alarm within 10 feet of bedroom doors; bedrooms with fuel burning appliances also need a CO alarm","Portable fire extinguisher (form still lists it): minimum 2A-10B:C, no more than 10 pounds, within 10 feet of the kitchen in the path of egress, mounted on the manufacturer's bracket with the top no more than 5 feet above the floor, serviced and tagged by a certified contractor within 12 months or a receipt for a recent purchase, with the owner's manual left for the new occupant","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Northfield City$t$, $t$b31d97dab45e50fe5f7a320f31f5891421ad3044aa99e102cb311c6a25714ee1$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0118.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0118.json$t$, true),
  ($t$0119$t$, $t$Pleasantville$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Permit (Change of Ownership) or Transfer of Ownership Permit (Certificate of Occupancy packet)$t$, $j$["Issued by: Code Enforcement Department (Housing Division)","Contact: Ben Silkowitz, Construction/Zoning Official (Code Enforcement / Housing Division phone listed) · 609-484-3633","Apply: The City packet says all applications take 7 to 10 business days for processing and inspection dates; the City Code says Code Enforcement acts within 10 days of a completed application.","How to apply: Download the Certificate of Occupancy packet from the City Forms page and complete the 'Occupancy Permit/Transfer of Ownership Permit' application (check 'Occupancy Permit - Change of Ownership', or 'Transfer of Ownership Permit' if the buyer will fix violations). Submit it to Code Enforcement (132 West Washington Avenue; mailing address 18 N. First Street) with the fee by check or money order payable to City of Pleasantville (no cash), plus the fire safety and heat/hot water certificates. Inspectors take scheduling calls from 8:30 to 9:30 am and 4:00 to 4:30 pm.","Valid for: Not stated. If no certificate or permit is issued within 3 months of the application, the application becomes void. A temporary occupancy permit lasts up to 3 months.","Fire safety certificate (smoke alarms, CO alarms) from the Pleasantville Fire Department","Heat and hot water heater certificate from a licensed plumber or HVAC technician (electric units do not need one)","Fireplace certification if there is one: gas units by an HVAC technician or plumber, wood burning fireplaces by a licensed chimney sweep","All utilities on at the time of inspection","Home fit for habitation under the City Property Maintenance Code: no fire or accident hazards, adequate ventilation, light and sanitary facilities, no dilapidation, disrepair, structural defects or uncleanliness","Buyers using an LLC must give the owner's or property caregiver's name and contact information","Transfer of Ownership Permit only: a signed, notarized statement from the new owner taking responsibility for correcting the code violations found; this permit does not allow occupancy","Also: Heat and hot water heater certificate: From any licensed plumber or HVAC technician; electric units do not need certification. Must be submitted with the CO application.","Also: Fireplace certification: If there is a fireplace: gas units by an HVAC technician or plumber, wood burning fireplaces by a licensed chimney sweep.","Also: Utilities on: All utilities must be on at inspection or the inspection is aborted and a $50 re-inspection fee applies."]$j$::jsonb, $j$[{"label":"Residential application (Occupancy Permit or Transfer of Ownership Permit), non-refundable","amount":"$60.00"},{"label":"Transfer of ownership permit, residential (City Code fee schedule, §300-9, amended 9-6-2023; the City form charges $60 for every residential application)","amount":"$40"},{"label":"Re-inspection, each","amount":"$50.00"},{"label":"Late cancellation (after 4:00 pm the day before)","amount":"$50.00"},{"label":"Inspection aborted because utilities are off","amount":"$50"},{"label":"Reprint after a name change within 5 days of printing","amount":"$2.00"}]$j$::jsonb, $t$https://www.pleasantville-nj.org/pdf/Certificate%20of%20Occupancy%20Form%20November%202023.pdf$t$, $t$https://www.pleasantville-nj.org/page.asp?var_incl=building.html$t$, $j$[{"url":"https://www.pleasantville-nj.org/pdf/Certificate%20of%20Occupancy%20Form%20November%202023.pdf","label":"Official source (pleasantville-nj.org)"},{"url":"https://ecode360.com/16165882","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/16163582","label":"Official source (ecode360.com)"},{"url":"https://www.pleasantville-nj.org/services/fire.asp","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/page.asp?var_incl=building.html","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/page.asp?var_incl=officials.html","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/government/forms.asp","label":"Official source (pleasantville-nj.org)"}]$j$::jsonb, $t$The City of Pleasantville requires a Certificate of Occupancy and a Yearly Rental Registration Certificate prior to occupancy of any rental property or sale of property.$t$, $t$cc23bb3002f46991822c6b59b0cb95340eabf9bb5a5e46650f97612dbd1ab2c9$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":6,"fee_bad":0,"fee_unchecked":6,"quotes":22,"q_ok":15,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0119.json$t$, true),
  ($t$0119$t$, $t$Pleasantville$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pleasantville Fire Department, Office of Fire Prevention (town fire bureau)","Contact: Anton Brown, Captain, Fire Official · 609-569-2042 · prevention@pleasantvillefd.net","Apply: Inspections are on Mondays and Wednesdays; the expedited fee gets a same or next business day inspection. Cancel at least 48 hours before the inspection.","How to apply: Complete the Application for Certification of Smoke Detector, Carbon Monoxide Detector, Portable Fire Extinguisher Compliance (check 'Sale') and bring it to the Office of Fire Prevention inside the Fire Department, 1 N. First Street (1st Street side door), 8:30 am to 4:30 pm on weekdays. Pay by check or money order payable to the City of Pleasantville; fees are non-refundable and mail-ins are not accepted.","Fire official in the NJ state directory, updated 5/26/2026: Anton Brown · (609) 484-3670 · Abrown@pleasantvillefd.net","Homes built before April 4, 1991: smoke alarm on each level including the basement (not attic or crawl space) and near each separate sleeping area","Homes built after April 4, 1991: smoke alarm on each level and in each bedroom, 110-volt interconnected with battery backup","Battery smoke alarms must be 10-year sealed (hardwired alarms excluded)","Carbon monoxide alarms in the immediate vicinity of the sleeping areas","Portable fire extinguisher: the 2025 application says it is required for multi-family properties only (excluding one- and two-family homes). The Fire Department web page still says extinguishers are required in 1, 2 and 3 family dwellings (page still lists it).","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate application, non-refundable","amount":"$60"},{"label":"Smoke/CO certificate, expedited (same or next business day)","amount":"$160"},{"label":"Duplicate certificate, each","amount":"$10.00"}]$j$::jsonb, $t$https://www.pleasantville-nj.org/pdf/Smoke%20Detector%20Carbon%20Monoxide%20Detector%20Fire%20Extinguisher%20Certification%20Application%20-%202025.pdf$t$, $t$https://www.pleasantville-nj.org/services/fire.asp$t$, $j$[{"url":"https://www.pleasantville-nj.org/pdf/Smoke%20Detector%20Carbon%20Monoxide%20Detector%20Fire%20Extinguisher%20Certification%20Application%20-%202025.pdf","label":"Official source (pleasantville-nj.org)"},{"url":"https://www.pleasantville-nj.org/services/fire.asp","label":"Official source (pleasantville-nj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$OFFICE: 609-569-2042$t$, $t$17a7d4dc64012a6e1daf598268f9a9be999795cda4b328f405a4adde73d3a8d5$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":6,"fee_bad":0,"fee_unchecked":6,"quotes":22,"q_ok":15,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0119.json$t$, true),
  ($t$0120$t$, $t$Port Republic$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) on change of ownership$t$, $j$["Issued by: Construction Office (Construction Official, with the subcode officials)","Contact: Pat Naticchione, Construction Official, Zoning Officer and Fire Inspector / Fire Subcode · 609-652-8759 · construction@portrepublicnj.org","Apply: Not stated. The Construction Office keeps office hours Tuesday and Thursday, 4:00 to 6:00 pm.","How to apply: The City Code requires the owner to request the certificate of continued occupancy from the Construction Official before the new owner occupies. No City CCO application form is posted online; contact the Construction Office (143 Main Street; 609-652-8759; construction@portrepublicnj.org), open Tuesday and Thursday 4:00 to 6:00 pm, to request the inspection.","Valid for: Not stated. A temporary certificate of continued occupancy, if granted, is valid for 180 days.","General inspection of the visible parts of the building; no pending violations or orders of the Construction Official","The current use of the building must have lawfully existed (checked against municipal records)","No violations of N.J.A.C. 5:23-2.14 and no unsafe conditions under N.J.A.C. 5:23-2.32(a)"]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy, per unit (City Code §102-4 fee schedule, amended 12-8-2015)","amount":"$100"},{"label":"Certificate of continued occupancy (older figure in City Code §102-9, added 1989; conflicts with the $100 fee schedule)","amount":"$25"}]$j$::jsonb, null, $t$https://www.portrepublicnj.org/construction-office/$t$, $j$[{"url":"https://ecode360.com/15407016","label":"Official source (ecode360.com)"},{"url":"https://www.portrepublicnj.org/construction-office/","label":"Official source (portrepublicnj.org)"}]$j$::jsonb, $t$A certificate of continued occupancy shall be required for the occupancy of any existing building or structure upon a change of ownership or upon a change to a new tenant.$t$, $t$abc05dada66df8bd2586f20dbfc266bdec756d8e52b2e09f01ee792aaa63d272$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-07","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0120.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-07. Source: property/data/municipal-requirements/checked/0120.json$t$, true),
  ($t$0120$t$, $t$Port Republic$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing (change of occupant) for the lowest fee.","How to apply: Apply online through the NJ DCA Division of Fire Safety portal (firesolutions.dca.nj.gov, smoke certification application) and pay online. The fee depends on how many business days before the closing the request is received. Questions: Bureau of Fire Code Enforcement, P.O. Box 809, Trenton, NJ 08625-0809.","Fire official in the NJ state directory (NJ DCA, state), updated 5/11/2022: Louis Kilmer · (609)633-6132","Smoke alarms on each level and outside each separate sleeping area, per N.J.A.C. 5:70-4.19 (battery-only alarms must be 10-year sealed units)","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (homes with a fuel-burning appliance or attached garage)","The 2025 state law (P.L.2025, c.19) removed the portable fire extinguisher from the state sale certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"NJ DCA smoke/CO certificate, requested more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"NJ DCA smoke/CO certificate, requested 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"NJ DCA smoke/CO certificate, requested fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Port Republic City$t$, $t$06440605ccc77af5eb9d91df7cbdc75d847cb3917c8f1b0c4adf91cfbd278721$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-07","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0120.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-07. Source: property/data/municipal-requirements/checked/0120.json$t$, true),
  ($t$0121$t$, $t$Somers Point$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Land/Structure Compliance (resale inspection; posted as 'Application Certificate of Occupancy')$t$, $j$["Issued by: Construction Official, Construction, Zoning and Code Enforcement Office (Dept. of Construction Enforcement)","Contact: Mark McCrane, Construction Official (Construction/Zoning Official) · 609-927-9088 x142 · mmccrane@spgov.org","Apply: Not stated.","How to apply: Fill out the Land/Structure Compliance Application (posted as 'Application Certificate of Occupancy' on the Construction, Zoning & Code Enforcement page) with the property use, occupancy, lockbox code, seller, agent, buyer, settlement date and whether the home will be rented, and submit it with the fee to the Construction Office (the form lists City Hall, 1 W. New Jersey Avenue; the web page lists 741 Shore Road), 9:00 am to 5:00 pm weekdays. The office-use section takes cash or check and records any open permits.","Valid for: Not stated.","Walks and driveways free of trip hazards","Yard free of weeds and debris, grass cut","House number at least 4 inches high, visible from the street","Paint not peeling or cracking, no untreated wood exposed","Service entry cable, gutters, downspouts, decks, steps and building exterior (foundation, walls, roof, glazing, basement hatch) in good condition; 3 or more risers need a graspable rail","Floor coverings without trip hazards; walls and ceilings in good condition","Smoke alarm within 10 feet of bedrooms and on every level including the basement; CO alarm within 10 feet of all sleeping rooms","Fire extinguisher 2A:10B:C, 10 lb maximum, mounted in the kitchen, visible and readily accessible, top no more than 5 feet above the floor (form still lists it)","Graspable rails on all stairs including the basement","Bathrooms have an operable window or a fan exhausting outside","GFCI protection on outlets within 6 feet of a sink and in the garage, basement and outside","A light fixture in every hallway, interior stairway, bathroom, kitchen, laundry room, boiler or furnace room and basement","Plumbing fixtures working with hot and cold water and no visible leaks; water heater relief valve discharge within 6 inches of the floor","Gas appliances vented with combustion air and clearances; dryer vented outside with metal flex duct; washer drains to the drain system","Door locks meet code (no double keyed locks); at least one insect screen in every room","Also: Open permits: The office-use section of the application records open permits for the property."]$j$::jsonb, $j$[{"label":"Land/Structure Compliance (CO) inspection, per dwelling unit","amount":"$250.00"},{"label":"Reinspection, each","amount":"$100.00"},{"label":"Reinspection appointment when smoke/CO alarms or extinguisher fail (older notice on page 2 of the same form, dated 2007)","amount":"$15"}]$j$::jsonb, $t$https://www.somerspointgov.org/pdfs/LAND%20STRUCTURE%20COMPLIANCE_0001.pdf$t$, $t$https://www.somerspointgov.org/mainpages/construction.asp$t$, $j$[{"url":"https://ecode360.com/11362402","label":"Official source (ecode360.com)"},{"url":"https://www.somerspointgov.org/pdfs/LAND%20STRUCTURE%20COMPLIANCE_0001.pdf","label":"Official source (somerspointgov.org)"},{"url":"https://www.somerspointgov.org/mainpages/construction.asp","label":"Official source (somerspointgov.org)"}]$j$::jsonb, $t$Upon the conveyance, or the entering into an agreement for the conveyance of any single-family dwelling, condominium unit or multifamily complex of four or fewer units, the Construction Official of the City of Somers Point shall conduct an inspection$t$, $t$6e24b5c8c9472f01163efedb63214d00f04ba6d9c2d3703a8440d52cb256ba36$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":8,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0121.json$t$, true),
  ($t$0121$t$, $t$Somers Point$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing (change of occupant) for the lowest fee.","How to apply: Apply online through the NJ DCA Division of Fire Safety portal (firesolutions.dca.nj.gov, smoke certification application) and pay online. The fee depends on how many business days before the closing the request is received. Questions: Bureau of Fire Code Enforcement, P.O. Box 809, Trenton, NJ 08625-0809.","Fire official in the NJ state directory (NJ DCA, state), updated 8/12/2025: Louis Kilmer · (609) 633-6132","Smoke alarms on each level and outside each separate sleeping area, per N.J.A.C. 5:70-4.19 (battery-only alarms must be 10-year sealed units)","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (homes with a fuel-burning appliance or attached garage)","The City's resale inspection form (2023) also checks smoke alarms, CO alarms and a 2A:10B:C extinguisher of 10 lb or less mounted to the kitchen wall, and notes 10-year sealed lithium battery smoke alarms have been required since 1/1/2019 (existing hardwired alarms excepted)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"NJ DCA smoke/CO certificate, requested more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"NJ DCA smoke/CO certificate, requested 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"NJ DCA smoke/CO certificate, requested fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.somerspointgov.org/mainpages/fire_inspect.asp","label":"Official source (somerspointgov.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City no longer maintains a Bureau of Fire Prevention and Inspection. This service is currently provided by the State of New Jersey.$t$, $t$2552f78b0feae56eed8a47aa98e53a465c87128fa7bc0702d3d668315ee22b71$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":8,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0121.json$t$, true),
  ($t$0122$t$, $t$Ventnor City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Sale Certificate of Occupancy and Certificate of Land Use Compliance$t$, $j$["Issued by: Building Code Official, Code Enforcement / Building Department (Housing); Land Use Administrator for the Land Use certificate","Contact: Dino Cavalieri, Code/Construction Official · 609-823-7987 · dcavalie@ventnorcity.org","Apply: The City Code says the Building Code Official inspects within 10 days of the application; the Land Use Administrator acts within 15 days of a completed application. Housing inspections run Monday to Friday, 9:30 am to 1 pm.","How to apply: Submit two forms from the Housing page to the Building / Code Enforcement Department, City Hall, 6201 Atlantic Avenue: the Sale Certificate of Occupancy Application (buyer, agent, proposed settlement date, whether smoke detectors are monitored, and the adults and children who will live in each unit) and the Application Certificate of Land Use Compliance (seller, property, zoning and use). A Certificate of Occupancy is needed per unit. Pay when the inspection is scheduled (cash, check or card). If the home is sold as is, the buyer becomes responsible for bringing it up to code before the CO is issued.","Valid for: Not stated. A new Certificate of Occupancy is needed whenever the occupants change.","Curb and sidewalk free of trip hazards (damaged sidewalk or curb must be repaired for the Land Use certificate)","House address posted","All railings and spindles in place (36 inch rail height)","Grass cut","Window screens in place from May 15 to October 1","ABC fire extinguisher with the gauge in the green, no larger than 10 pounds, mounted within 10 feet of the kitchen (required for sales; City pages still list it)","Smoke alarms in each bedroom, on each level and within 10 feet of all bedrooms; CO alarm on each sleeping floor and near any major gas appliance","If smoke detectors are monitored, a certificate from the alarm company","Dryer vented to the exterior","Electric on and appliances working","Two outlets in each bedroom; bathroom outlet plus a fan or exhaust window","Water heater pressure relief valve discharge checked","Blanks in the electric panel","Unit clean: no mold in tub, clean rugs, no chipping paint","Also: Certificate of Land Use Compliance: A separate Land Use application (seller, property, zoning classification and use) is needed with the Sale CO; damaged sidewalk or curb must be repaired as part of the review. Fee $100.","Also: Alarm company certificate: If smoke detectors are monitored, a certificate from the alarm company is required."]$j$::jsonb, $j$[{"label":"Sale Certificate of Occupancy, non-refundable (form updated 4/11/25)","amount":"$100"},{"label":"Certificate of occupancy (City Code fee schedule §114-23, amended 4-10-2025)","amount":"$100"},{"label":"Certificate of Land Use Compliance (application form)","amount":"$100.00"},{"label":"Certificate of land use compliance (City Code fee schedule §114-11, amended 4-10-2025)","amount":"$100"},{"label":"Each form, per Code Enforcement FAQ (older figure; conflicts with the current forms and City Code)","amount":"$50.00"}]$j$::jsonb, $t$https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf$t$, $t$https://www.ventnorcity.org/departments/CodeEnforcement/housing$t$, $j$[{"url":"https://ecode360.com/8288972","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/37947710","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8286731","label":"Official source (ecode360.com)"},{"url":"https://ventnorcity.org/departments/CodeEnforcement/code-enforcement-faq","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/media/Documents/CodeEnforcement/LAND%201.26.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://www.ventnorcity.org/departments/staff_directory/CodeEnforcement/","label":"Official source (ventnorcity.org)"}]$j$::jsonb, $t$No owner or occupant of a dwelling, dwelling unit, rooming unit, apartment or premises (hereinafter dwelling) and no person or entity on behalf of the owner or occupant shall sell, rent, transfer or otherwise dispose of any ownership interest or occupancy thereof,$t$, $t$1a334586d73b9627fe35aad28c266b6579a9b92e7edb02f45f442fa079d54d8c$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":1,"fee_bad":0,"fee_unchecked":4,"quotes":19,"q_ok":8,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0122.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0122.json$t$, true),
  ($t$0122$t$, $t$Ventnor City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ventnor City Building / Code Enforcement Department (smoke, CO and extinguisher check within the Sale Certificate of Occupancy) (town fire bureau)","Contact: Dino Cavalieri, Code/Construction Official · 609-823-7987 · dcavalie@ventnorcity.org","Apply: Part of the Sale CO inspection; Housing inspections run Monday to Friday, 9:30 am to 1 pm.","How to apply: No separate smoke certificate application or fee was found. The City's Certificate of Occupancy requirements letter says smoke alarms, CO alarms and portable fire extinguishers are required before any Certificate of Occupancy is issued, and the state fire directory lists the Ventnor City Building Department for smoke detector compliance, so the check is made during the Sale Certificate of Occupancy inspection.","Fire official in the NJ state directory, updated 5/26/2026: Joseph Iannuzzelli · (609) 823-7943 · jiannuzzelli@ventnorcity.org","Smoke alarms: one in each bedroom, one on each level, and one within 10 feet of all bedrooms (battery or hardwired accepted)","Carbon monoxide alarm on each sleeping floor and near any major gas burning appliance, per the manufacturer's instructions","Portable fire extinguisher, required for sales only: ABC type, no larger than 10 pounds, mounted within 10 feet of the kitchen, gauge in the green (City letter, 2008 scan, and current FAQ still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.ventnorcity.org/media/Documents/CodeEnforcement/SALE%201.26.pdf$t$, $t$https://www.ventnorcity.org/departments/CodeEnforcement/housing$t$, $j$[{"url":"http://www.ventnorcity.org/media/Documents/CodeEnforcement/FillableForms/CERTIFICATE%20OF%20OCCUPANCY%20REQUIREMENTS.pdf","label":"Official source (ventnorcity.org)"},{"url":"https://ventnorcity.org/departments/CodeEnforcement/code-enforcement-faq","label":"Official source (ventnorcity.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.ventnorcity.org/departments/Fire/fire-prevention","label":"Official source (ventnorcity.org)"}]$j$::jsonb, $t$are now required prior to the issuance of any Certificate of Occupancy under the Uniform Construction Code Act 52:27D-133.3.$t$, $t$843eb800679024766d98a4706905f6713158f8809489191b94cb1340b50ae260$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":1,"fee_bad":0,"fee_unchecked":4,"quotes":19,"q_ok":8,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0122.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0122.json$t$, true),
  ($t$0123$t$, $t$Weymouth Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale (Housing Office)$t$, $j$["Issued by: Housing Office (Housing Officer)","Contact: Chase Farabella, Housing Officer · 609-476-2633 ext 3 · housing@weymouthnj.org","Apply: The Housing Officer inspects within 14 days of receiving the completed application and payment; the Township Code says the CO is issued, or violations are sent, within three working days after the inspection.","How to apply: Complete the Application for Certificate of Occupancy (check 'Certificate of Occupancy - Sale'; give block, lot, settlement date, owner and the contact person for the inspection appointment) and return it with the $50.00 inspection fee to the Housing Officer, 45 South Jersey Avenue, Dorothy, NJ 08317. The Housing Officer inspects within 14 days. Separately get the NJ DCA smoke/CO certificate online; the Township will not issue the CO until it receives it.","Valid for: Until the premises become vacant, are sold to a new owner, or there is a conviction for a code violation (Township Code §106-6F).","Housing Officer inspection: the home must be fit for human habitation (no fire or accident hazards; adequate ventilation, light and sanitary facilities; no dangerous plumbing or heating defects; no dilapidation, disrepair or structural defects; no uncleanliness or infestation; no construction code violations)","The Township will not issue the CO until it receives a valid NJ DCA Division of Fire Safety smoke alarm, carbon monoxide alarm and portable fire extinguisher certificate","Also: NJ DCA smoke/CO certificate before the Township CO: The Township CO is not issued until the Township receives the DCA smoke/CO certificate."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy - Sale inspection (application form)","amount":"$50.00"},{"label":"Inspection of any house or part of a duplex (Township Code §106-7A, amended 5-15-2024); the first reinspection is free, later reinspections cost another inspection fee","amount":"$50"}]$j$::jsonb, $t$https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/CO-Application-8-2026%20updated.pdf$t$, $t$https://www.weymouthnj.org/township_offices/housing_office/index.php$t$, $j$[{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/CO-Application-8-2026%20updated.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://ecode360.com/11406861","label":"Official source (ecode360.com)"},{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/DCA-Smoke-Detector-info-08-2026.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://www.weymouthnj.org/township_offices/housing_office/index.php","label":"Official source (weymouthnj.org)"}]$j$::jsonb, $t$Request for ( ) Certificate of Occupancy - Sale ( ) Certificate of Occupancy - Rental$t$, $t$2e15018bfa88e334fc9658968b5c5cc002357db16e46363ddf52f381b73bbcb4$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0123.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0123.json$t$, true),
  ($t$0123$t$, $t$Weymouth Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing (change of occupant) for the lowest fee.","How to apply: Apply online through the NJ DCA Division of Fire Safety portal (firesolutions.dca.nj.gov, smoke certification application) and pay online. The fee depends on how many business days before the closing the request is received. Questions: Bureau of Fire Code Enforcement, P.O. Box 809, Trenton, NJ 08625-0809.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","Smoke alarms on each level and outside each separate sleeping area, per N.J.A.C. 5:70-4.19 (battery-only alarms must be 10-year sealed units)","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (homes with a fuel-burning appliance or attached garage)","The Township's information sheet (revised 08/26/26) still describes the extinguisher rule: minimum 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen stove in the exit path, top no more than 5 feet above the floor on the manufacturer's bracket, serviced and tagged by a DFS-certified contractor within 12 months or a recent purchase receipt (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"NJ DCA smoke/CO certificate, requested more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"NJ DCA smoke/CO certificate, requested 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"NJ DCA smoke/CO certificate, requested fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.weymouthnj.org/Document%20Center/Forms%20and%20Documents/Housing%20Forms/DCA-Smoke-Detector-info-08-2026.pdf","label":"Official source (weymouthnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application for the Smoke Detector and Carbon Monoxide Alarm and Fire Extinguisher Compliance Certificate is obtained on line at https://firesolutions.dca.nj.gov/$t$, $t$8a10a89ae3d9ecf1a0f7a07d86aaef2fb926c439747dfdfbf07fafb6c3d44f90$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":7,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0123.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0123.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Change in Occupancy or Ownership (Resale/Rental Certificate)$t$, $j$["Issued by: Springfield Township Construction Office","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: Download the Resale/Rental Application (Rev. Mar 2025) from the Construction Office resources, check \"Sale\", sign it, and submit it with a check or money order for $150.00 payable to \"Springfield Township\" to the Construction Office, 2159 Jacksonville-Jobstown Road, Jobstown, NJ 08041. The fee is non-refundable. Inspection results and the certificate are sent by email.","Smoke alarms on every level and outside each sleeping area: 10-year sealed battery alarms, or hardwired where required","Basement alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms close to all bedrooms","Smoke alarms less than 10 years old (or not past the maker's expiration date) and working","Hardwired smoke alarms required by the building code cannot be replaced with battery alarms","Homes with a monitored low-voltage fire alarm system: have it tested by the alarm company before the inspection and bring the certification","CO alarm in the hallway close to all bedrooms, less than 10 years old, UL listed and working","Fire extinguisher rated 2A-10B:C, no more than 10 lb, within 10 feet of the kitchen in the path of egress, top no more than 5 feet above the floor, on the maker's bracket, not in a closet or behind a door; leave the manual for the new occupant (March 2025 checklist)","House numbers at least 3 inches, contrasting, permanently fixed to the house and visible from the street","No open Springfield Township construction permits; all permitted work finalized and passed","Also: Open construction permits closed: No outstanding Springfield Township construction permits; all permitted work must be finalized and passed before the resale inspection passes.","Also: Rental registration deactivated: If the property was a rental, the landlord registration is deactivated on the resale application."]$j$::jsonb, $j$[{"label":"Resale inspection (includes two inspections)","amount":"$150.00"},{"label":"Each additional inspection after the first two","amount":"$65.00"}]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://www.springfieldtownshipnj.org/constructionoffice","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2FkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=Jfp%252B3K9fyAYWIble3%252BR4eQ%3d%3d&eb=0xG5h%252BICHBzdF1eDwLDXRA%3d%3d","label":"Official source (app.membershipware.com)"}]$j$::jsonb, $t$The Springfield Construction Office is responsible for construction permits, plan reviews, inspections, and Resale / Rental Certificates as allowed by the State of New Jersey and the Springfield Township code.$t$, $t$535de88c46f11223c70a4d2b9dd562cde8087c729a2ec06ef57aa27b45524f09$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":2,"fee_unchecked":0,"quotes":15,"q_ok":7,"q_bad":6,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Springfield Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: The smoke alarm, CO alarm and extinguisher checks (N.J.A.C. 5:70-4.19) are part of the $150 resale inspection; see the resale certificate section. No separate smoke certificate form or fee was found.","Fire official in the NJ state directory (NJ DCA, state), updated n/a: Louis Kilmer · (609)633-6132","10-year sealed battery smoke alarms (or hardwired as required) on every level and near all bedrooms; alarms under 10 years old","Hardwired alarms cannot be replaced with battery alarms","CO alarms under 10 years old in the hallway near all bedrooms","Fire extinguisher 2A-10B:C, 10 lb maximum, mounted within 10 feet of the kitchen, top no higher than 5 feet (March 2025 township checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2FkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"}]$j$::jsonb, $t$S Springfield Township$t$, $t$01ef69bd4f4d91b012a715a6eb92e1826f4b1ae94989a83831cc38aac6dd38e8$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":2,"fee_unchecked":0,"quotes":15,"q_ok":7,"q_bad":6,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale housing inspection)$t$, $j$["Issued by: Willingboro Township Inspections Department (Department of Code Enforcement and Inspections)","Contact: Shaleen Bolling-Gonzalez, Housing / Rental / Resales · 609-877-2200 ext. 1033","Apply: The township advises scheduling the inspection within 30 days of the settlement date, because the CO is good for 30 days. All violations must be reinspected within 30 days of the first inspection.","How to apply: Fill out the Resale Inspection Housing Application in the township's 'Moving' packet and submit it with the $150 fee to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, Willingboro. The form's office section lists check, cash or credit card. The Inspections page says resale/rental applications can also be submitted and paid online (the portal link is not shown on the page). The seller or agent can schedule the inspection; a lock box number lets the inspector enter. Give 24 hours notice to cancel or reschedule or the fee is still charged.","Valid for: 30 days","Township housing inspection of the whole house, inside and out; all violations corrected before the CO is issued","Exterior: driveway and walks free of cracks or raised sections; lawn, trash and debris cleaned up; fence stable; screens in windows (May 1 to Oct 1)","Roof: no missing or broken shingles, maximum 2 layers; siding and gutters in repair; peeling paint scraped and repainted","House number: 6 inch numbers on the building","Interior: walls, ceilings and floors in good repair; working lights, outlets and switches with cover plates; windows open and stay up; no double-keyed deadbolts","Kitchen and bath: working burners, plumbing without leaks, exhaust fan or window, cabinets in good condition","Handrails on all staircases; garage conversions may need permits","Smoke and CO detectors within 10 feet of bedrooms; smoke alarms must be ten-year sealed battery type","Portable fire extinguisher (still listed on the township checklist): at least 2:A:10B:C, no more than 10 lbs, mounted within 10 ft of the kitchen and not more than 5 ft above the floor","Electric service panel with covers, working and labeled breakers; water heater with pressure relief pipe and bonding","Original heating certificate from a Willingboro-registered heating contractor (valid 30 days)","Private sewer lateral video inspection report from a master plumber showing no repairs needed (valid 6 months)","Open construction permits must be passed and closed; work done without permits must be permitted","Copy of a current property survey for all resales","Also: Heating certificate: Original heating system certificate from a heating contractor on the township registered list, valid 30 days, must be brought in to get the CO.","Also: Private sewer lateral inspection: Seller must hire a master plumber or utility contractor for a video inspection and certified Private Sewer Lateral Inspection Report (Ordinance 2021-13, Chapter 291). Repairs must be done before the CO; a satisfactory report is good for 6 months. Start once the home is listed, no later than the agreement of sale.","Also: Open permits: Open construction permits are checked and must have final inspections; work done without permits must be permitted. The CO will not be issued until all permits are passed and closed out.","Also: Property survey: A copy of a current survey of the property must be submitted before a certificate can be issued for all resales.","Also: Flood hazard letter: The resale CO includes a flood hazard letter and certificate of housing code along with the smoke detector certification.","Also: Certified tax search and added assessment: Certified tax search request goes to the Tax Collector with a $10.00 fee (per the packet form); see the Tax Assessor about added assessments for improvements."]$j$::jsonb, $j$[{"label":"Resale housing inspection (includes one re-inspection within 30 days)","amount":"$150.00"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF$t$, $t$https://www.willingboronj.gov/243/Inspections-Code-Enforcement$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/m/directory/department?did=20","label":"Official source (willingboronj.gov)"}]$j$::jsonb, $t$Did you know Willingboro Township requires all homes to be transferred or sold to have an inspection done by a Willingboro Township Housing Inspector.$t$, $t$8cf67c993b582af647a4eca822309fa0d78b1e2f31b7378858a0bd3563c948d3$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Willingboro Township Inspections Department (town fire bureau)","Contact: Dennis Tunstall, Director, Inspections · 609-877-2200 ext. 1214","How to apply: For a sale, the township's resale Certificate of Occupancy includes the smoke detector certification, so the $150 resale housing inspection covers it. The township also posts a separate Application for Certificate of Compliance (smoke detectors, CO alarms, fire extinguisher; $150) inspected by a township inspector; submit it to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, and give 24 hours notice to cancel or reschedule or the fee is forfeited.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609) 633-6132","Smoke detector on each level including basements (not attics or crawl spaces)","Smoke detector and CO alarm outside each separate sleeping area and within 10 feet of bedrooms","Battery smoke alarms must be the ten-year sealed type (township checklist)","The township forms (2026 Certificate of Compliance and the resale checklist) still require a fire extinguisher within 10 feet of the kitchen, rated at least 2:A:10B:C and no more than 10 lbs, mounted with the manufacturer bracket not more than 5 ft above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke, CO alarms and fire extinguisher) inspection, when applied for separately","amount":"$150.00"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF$t$, $t$https://www.willingboronj.gov/245/Inspection-Forms$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A CERTIFICATE OF COMPLIANCE IS REQUIRED ON ALL HOMES BEING TRANSFERRED OR SOLD PRIOR TO OCCUPANCY$t$, $t$ebb230fc0c3d7b0b948ee1e8c9e1e96cb1ad7da5ad4696acd3d25cdef79daa26$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":17,"q_ok":8,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale or Resale of Property$t$, $j$["Issued by: Borough of Audubon (requests handled by the Administrative Assistant to the Superintendent of Public Works; interior fire inspection by the Fire Marshal, exterior inspection by the Borough)","Contact: 856-547-1240 ext. 110 · k.melvin@audubonnj.com","Apply: Submit the request at least 15 business days before settlement; inspections and responses typically take 7 to 10 business days","How to apply: Only the seller or the seller's agent (attorney, agent or property manager) may request; buyers and buyers' agents cannot. Fill out the 2026 CO application (or email the seller name, property address, closing date and whether there is a sump pump) to Kristen Melvin at k.melvin@audubonnj.com. Pay with two separate payments ($50 exterior and $25 fire) by check or money order payable to Borough of Audubon, or exact cash. No credit, debit or online payments. Payments can be mailed, brought in person, or left in the black vestibule lockbox marked Attention: CO. Call the Construction Office first to make sure all permits are closed.","Valid for: 90 days from the date of issuance","Two inspections must both pass: an interior fire inspection and an exterior property inspection","Sidewalks, walkways, driveways, driveway aprons, steps and pavers must be free of cracks, raised or uneven surfaces, deterioration and trip hazards","Ramping a raised sidewalk joint is not an acceptable repair","Smoke and CO detectors must be UL listed, have a 10-year sealed battery, and be no more than 10 years old","Hardwired smoke alarms cannot be swapped for battery units; hardwired units must be interconnected and working","Smoke detector on every level (basement, each floor, and a finished or used attic) and in every bedroom","Working smoke and CO detector within 10 feet of all bedrooms","House numbers at least 4 inches tall, contrasting, visible from the street","No double-cylinder (keyed both sides) deadbolts on exit doors; exits must open from inside without a key","Sump pumps, roof drains and other discharges may not be connected to the sanitary sewer","All liens and property maintenance charges resolved and all construction permits closed before the CO is issued","Also: Open construction permits must be closed: Sellers must contact the Construction Office to make sure all permits are closed before applying: (856) 547-6312, n.bicking@audubonnj.com.","Also: Liens and property maintenance charges: All liens and outstanding property maintenance charges must be resolved before the CO is issued.","Also: Sump pump / drainage disclosure: The request must state whether there is a sump pump; sump pumps and roof drains may not discharge into the sanitary sewer."]$j$::jsonb, $j$[{"label":"Exterior property inspection","amount":"$50"},{"label":"Interior fire inspection (paid separately)","amount":"$25"},{"label":"Exterior inspection, per 2026 application form (separate check or money order)","amount":"$50.00"},{"label":"Fire inspection, per 2026 application form (separate check or money order)","amount":"$25.00"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info$t$, $j$[{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f","label":"Official source (audubonnj.com)"}]$j$::jsonb, $t$A Certificate of Occupancy (CO) is required for the sale or resale of all residential and non-residential properties in the Borough of Audubon, whether occupied or vacant.$t$, $t$8d92e5ebc1c7eff042e0e4d997b8875123adcac94586943f6f2ae0bddab4cb14$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Audubon Fire Marshal's Office (town fire bureau)","Contact: 856-547-0710 ext. 117","Apply: Part of the resale CO request; submit at least 15 business days before settlement","How to apply: Requested together with the resale CO through Kristen Melvin (k.melvin@audubonnj.com, 856-547-1240 ext. 110). Pay the $25 fire fee as its own check, money order or exact cash, separate from the $50 exterior fee.","Fire official in the NJ state directory (town), updated n/a: Ernest F Busch · (856) 546-5399 · ebusch@haddonfield-nj.gov","Smoke and CO alarms must be UL listed with a 10-year sealed battery and no more than 10 years old","Hardwired smoke alarms may not be replaced with battery-only units and must be interconnected","Smoke alarm on every level including basement and a finished or used attic, plus one in every bedroom","Smoke and CO alarm within 10 feet of all bedrooms (combination units allowed)","House numbers at least 4 inches tall and visible from the street","No double-cylinder deadbolts on exit doors","Fire inspections are Thursday mornings only; someone must be present or a lockbox code provided","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Interior fire inspection (resale)","amount":"$25"},{"label":"Fire inspection, requirements sheet","amount":"$25"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/fs/resource-manager/view/683dc676-1b13-445c-9e63-e74ff15a5309$t$, $j$[{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/683dc676-1b13-445c-9e63-e74ff15a5309","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$State law requires a fire inspection before any sale, and failure to comply may result in state fines.$t$, $t$222b81cc97e9ea2040689d3d14de027aa7d2f4a5bbcce68fc0ccf41da8fdcf01$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale CO (made up of the Fire Marshal smoke detector certificate of compliance plus the sidewalk inspection certificate of compliance)$t$, $j$["Issued by: Borough of Haddonfield Construction and Zoning Office (Community Development), with the Bureau of Fire Prevention (Fire Marshals) and the Sidewalk Inspector","Contact: 856-429-4700 · SKrohn@haddonfield-nj.gov","Apply: Notify the Borough at least 30 days before transfer of title (or within 5 days of signing the sales contract, whichever is later) for the sidewalk inspection. Lower fees apply if applications are submitted more than 10 business days before settlement.","How to apply: Submit the Smoke Detector form, Sidewalk Inspection form and (if in the Historic District) the Historic District Disclosure form to the Construction and Zoning Office, Room 104, Borough Hall, 242 Kings Highway East, with the fees in cash or check payable to the Borough of Haddonfield. Staff check permit history first. Schedule the smoke inspection directly with the Fire Marshal. Sidewalk inspections happen Tuesdays and Thursdays without an appointment; results are emailed.","Valid for: 90 days","All construction permits must be inspected and closed before the CO is released","Sidewalks, driveway aprons and walkways in the public right-of-way free of trip hazards (no lifts, holes or height differences of 1/2 inch or more)","Sidewalk repairs completed and the Borough notified at least 7 days before title transfer, or money placed in escrow and repairs done within 30 days after closing","Smoke alarm on every level (10-year sealed battery if battery powered)","CO alarm outside the bedroom area","ABC portable fire extinguisher no larger than 10 lb, within 10 feet of the kitchen","Street number at least 4 inches, contrasting and readable from the street","Historic District disclosure form if the home is in the Historic District","Also: Open construction permits must be closed: Staff check permit history; all permits must be inspected and closed before the Resale CO is released, and no smoke inspection is scheduled while permits are open.","Also: Sidewalk and driveway apron inspection: Required on every sale; repairs or escrow before closing.","Also: Historic District disclosure: Buyers must be notified if the property is in the Historic District (Ch. 135-60). No fee.","Also: Move-out/move-in trash pickup: Schedule with Public Works at 856-429-0183 before putting out excess trash."]$j$::jsonb, $j$[{"label":"Sidewalk inspection, settlement more than 10 business days away (includes first re-check after repairs)","amount":"$50"},{"label":"Sidewalk inspection, settlement less than 10 business days away","amount":"$75"},{"label":"Sidewalk re-inspection, each (beyond the first re-check)","amount":"$25.00"},{"label":"Sidewalk late notice fee, each failure to give timely notice","amount":"$25.00"},{"label":"Historic District Disclosure Form","amount":"no fee"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071$t$, $t$https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$Selling a Home in the Borough of Haddonfield Resale CO 1. Smoke Detector Form / Fire Marshall CO Inspection$t$, $t$7c020edbbb4ac098da374070061375241398678d9a20f55130f263cbfcbf3a79$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":9,"fee_bad":1,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haddonfield Bureau of Fire Prevention (Office of the Fire Marshal) (town fire bureau)","Contact: 856-429-4308 ext. 504/505 · EBusch@haddonfield-nj.gov","Apply: Lowest fee if submitted more than 10 business days before settlement","How to apply: Submit the Sale and Rental of Residential Property Ordinance Compliance Application with payment (cash or check to the Borough of Haddonfield) at the Construction and Zoning Office, Room 104, Borough Hall. Then schedule directly with the Fire Marshal's Office; inspections are Tuesdays or Wednesdays, 9 a.m. to 1 p.m. If it passes, a copy of the approval is left on site.","Fire official in the NJ state directory (town), updated 5/18/2026: Ernest F Busch · (856) 429-4308 · ebusch@haddonfield-nj.gov","All single-station battery smoke alarms must be the 10-year sealed battery type","Hardwired (110-volt) smoke detectors maintained per manufacturer and the code in effect at installation","ABC-type extinguisher, no larger than 10 lb, within 10 feet of the kitchen area","Street number at least 4 inches, contrasting, readable from the street","Form includes a check for a secondary power source","No inspection is scheduled until all open permits are closed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Submitted more than 10 business days before settlement","amount":"$56"},{"label":"Submitted 4 to 10 business days before settlement","amount":"$125"},{"label":"Submitted fewer than 4 business days before settlement","amount":"$201"},{"label":"First re-inspection","amount":"no additional charge"},{"label":"Each additional re-inspection (prepaid)","amount":"$25"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260616113807071$t$, $t$https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260616113807071","label":"Official source (haddonfieldnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Borough of Haddonfield, Bureau of Fire Prevention is responsible for inspection of all one- and two-family dwelling units.$t$, $t$60c44c0a7d2cdce1602bf9f31bb6cb884de6eea19a1435dc8603279ec9e13d7c$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":9,"fee_bad":1,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) / Certificate of Compliance$t$, $j$["Issued by: Zoning Officer / Code Enforcement Officer (Zoning and Code Enforcement)","Contact: 856-546-2580 · zoning@haddonhts.com","Apply: No application can be filed without a settlement date. All fees must be paid before scheduling an inspection.","How to apply: Fill out the CCO application (needs a settlement date) and return it with payment (check or cash) to Zoning and Code Enforcement, 514 W. Atlantic Avenue, Haddon Heights. The applicant is responsible for scheduling all inspections and re-inspections after fees are paid."]$j$::jsonb, $j$[{"label":"Application filing fee","amount":"$11.00"},{"label":"First inspection","amount":"$50.00"},{"label":"Second inspection","amount":"no charge"},{"label":"Third or later inspection, each","amount":"$25.00"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO$t$, $t$https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy$t$, $j$[{"url":"https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO","label":"Official source (haddonhts.com)"}]$j$::jsonb, $t$Per Ordinance 2018:1453, no residential properties may change ownership or tenancy until a Certificate of Continued Occupancy (CCO) is issued by the Zoning Officer and a Smoke Detector/Carbon Monoxide Inspection is also required by the Fire Department.$t$, $t$3663657cffb47e211b142bba1e7ebc0213b8fce435cdbb6ad60dc86a7a39f2fc$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":7,"q_ok":6,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Heights Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: 856-546-7135 ext. 81","Apply: Lowest fee with 8 or more days advance notice; schedule early","How to apply: Fill out the Request for Inspection form and email it to one of the fire inspectors, fax it to 856-546-5340, or bring it to the office at 608 Station Avenue. Checks payable to Borough of Haddon Heights.","Fire official in the NJ state directory, updated 7/22/2026: Benjamin Zwaska · (856) 546-7135 · bzwaska@haddonhts.com","One smoke detector on each level including basement and any attic reachable by stairs; each level of each unit in a two-family","Ceiling-mounted at least 4 inches from walls, at least 36 inches from cold air returns and bathroom doors, away from ceiling fans; wall-mounted 4 to 12 inches below ceiling","UL-approved CO detector in the vicinity of each sleeping area","House number visible from the street, Arabic numerals at least 3 inches","2-A:10-B:C extinguisher no more than 10 lbs, charged, in a conspicuous place no more than 10 feet from the kitchen, instructions visible","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"8 or more days advance notice","amount":"$75.00"},{"label":"4 to 7 days advance notice","amount":"$100.00"},{"label":"3 or fewer days advance notice","amount":"$140.00"},{"label":"Re-inspection","amount":"$35.00"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB$t$, $t$https://www.haddonhts.com/1336/Fire-Prevention$t$, $j$[{"url":"https://www.haddonhts.com/1336/Fire-Prevention","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB","label":"Official source (haddonhts.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SELLING YOUR HOME? The Bureau of Fire Prevention also handles the Certificate of Smoke Detector and Carbon Monoxide Compliance (CSDCMAC). This inspection is required prior to selling your home.$t$, $t$3cb3fa2b971ba2a11ef440ebb6cceb341e8057c9463ebfc1c0b7ab7c6dc1e65f$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":7,"q_ok":6,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Hi-Nella Borough requires a resale certificate. Call the office before closing.","Contact: 856-784-6237 ext. 400 · clerkhinellaboro@comcast.net"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.hinellaboro.org/contact$t$, $j$[{"url":"https://www.hinellaboro.org/contact","label":"Official source (hinellaboro.org)"}]$j$::jsonb, $t$Construction DCA (609) 567-3653$t$, $t$ab3534a705d0c6f0b401ca33fe791462b9edd314315b979beba46a0a152b7003$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Borough of Barrington Bureau of Fire Prevention) (town fire bureau)","Contact: 856-547-0991 · firealliance@barringtonboro.com","Apply: Lowest fee with 14 or more business days notice before the change of occupant (weekends, holidays and the settlement date do not count)","How to apply: Fill out the Alliance's certificate application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox or mail it to 205 Haines Avenue, Barrington, NJ 08007. A check or money order payable to 'Regional Fire Prevention Alliance' must go with the application. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 5/18/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; take them down and check the date, replace if undated","Smoke alarm type by build year: pre-1975 homes need 10-year sealed battery alarms on each level; newer homes need hardwired, interconnected alarms per the year-built chart","Smoke alarm in each sleeping area plus one outside each sleeping area within 10 feet (local ordinance 172-8 B)","CO alarm outside of and near all sleeping areas if there is a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers: Arabic numerals at least 3 inches, contrasting, at least 60 inches above ground, visible from the street","Homes with a secondary power source (solar, generator, battery storage) need a printed label within 18 inches of the main panel and meter, like \"CAUTION MULTIPLE SOURCES OF POWER\"","Fire extinguisher (June 2025 form): fully charged 2-A:10-BC in or within 10 feet of the kitchen, visible, mounted no higher than 5 feet, and either under 1 year old or tagged by a NJ certified fire equipment contractor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8 to 13 business days before","amount":"$74.00"},{"label":"Request received 4 to 7 business days before","amount":"$106.00"},{"label":"3 business days or less notice","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$59dd7f0268d4cb1bcb1bc20437e326ed24931446e748cf3a3e991101f3aea4ad$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Property Compliance (CPC)$t$, $j$["Issued by: Borough of Laurel Springs Office of Property Maintenance and Fire Prevention (Property Maintenance Officer / public officer)","Contact: 856-784-0500 · dkrawchuk@laurelsprings-nj.com","Apply: Notify at least 10 days before the change in occupancy; higher fees for 4 to 9 days and 1 to 3 days notice","How to apply: Fill out the Certificate of Property Compliance form (and the Fire Safety Certificate form for a sale) and pay at Borough Hall, 723 West Atlantic Avenue, payable to the Borough of Laurel Springs. Inspectors are notified by email only after payment is received. Fees are non-refundable. The inspector leaves a copy at the property.","Valid for: 45 days from the date of inspection","No refuse, garbage, abandoned vehicles, or overgrown brush, weeds or trees","Sidewalks and driveways free of holes; no standing stormwater","Foundation, walls, chimney, roof shingles and gutters in good repair","Porches, landings, stairs, balconies and railings safe","No broken glass or doors; windows and doors working","Working smoke detectors and CO detector","Central heating, air conditioning, kitchen, baths and light fixtures in working order","No fire or electrical hazards","Basement and crawl space condition","Property tax, sewer and property code fee balances are checked by Borough staff","Also: Tax, sewer and code fee balances checked: Borough Hall staff record property tax, sewer utility fee and property code fee status on the CPC form.","Also: Lead-safe certificate question: The CPC form asks whether the owner has a valid lead-safe certificate."]$j$::jsonb, $j$[{"label":"CPC, home resale, 10+ days notice","amount":"$50"},{"label":"CPC, home resale, 4 to 9 days notice","amount":"$70"},{"label":"CPC, home resale, 1 to 3 days notice","amount":"$125"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance$t$, $t$https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance","label":"Official source (laurelsprings-nj.com)"}]$j$::jsonb, $t$Whenever there shall occur a change in occupancy in any residential property, including one- and two-family homes and apartments, a new certificate of property compliance shall be required. A change in occupancy shall occur in an apartment by a change in tenant or by the execution of a new lease with a new tenant, and in all other dwelling units by sale or lease.$t$, $t$88d9df4d8c4f93b401c6500c514579c4a367ab71a5844c9eccc6f18959f87f8a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Laurel Springs Office of Fire Prevention and Property Maintenance (Fire Marshal) (town fire bureau)","Contact: 856-784-0500 ext. 25 · kcheeseman@laurelsprings-nj.com","Apply: Ten days notice is required for all inspections","How to apply: Fill out the Fire Safety Certificate of Compliance form and pay at Borough Hall (payable to the Borough of Laurel Springs) together with the CPC. The Fire Marshal is notified by email after payment.","Fire official in the NJ state directory, updated 5/22/2026: Kenneth Cheeseman · (856) 784-0500 · kcheeseman@laurelsprings-nj.com","Working smoke alarms on every level including basement and within 10 feet of bedroom doors; type depends on build year (hardwired and interconnected for newer homes, in every bedroom for 1991/1992 and later)","Hardwired smoke detectors may not be replaced with battery units; interconnected detectors must be replaced with compatible ones","Basement detector within 10 feet of the stairway, not in the stairway","Two-family homes: detectors at each landing of common hallways and stairs","Do not place detectors within 5 feet of a kitchen, 3 feet of fans, bathroom doors or supply vents, or 1 foot of a light fixture; detectors must not be painted","Central-station monitored alarm systems must be certified by a licensed NJ Fire Protection Contractor before the Fire Marshal's inspection","CO alarm on each sleeping level, in the hallway near every bedroom door, if there is a fuel-burning appliance or attached garage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Safety Inspection, home resale, 10+ days notice","amount":"$45"},{"label":"Fire Safety Inspection, home resale, 4 to 9 days notice","amount":"$90"},{"label":"Fire Safety Inspection, home resale, 1 to 3 days notice","amount":"$161"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF$t$, $t$https://www.laurelsprings-nj.com/1359/Fire-Safety-Requirements-Smoke-Detectors$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF","label":"Official source (laurelsprings-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In the case of the resale of a property, both a Certificate of Property Compliance and Fire Safety are required.$t$, $t$19efa60a462214b186fe7bf469811e3bab49670ac3f62e7e3f74e913a2535b6d$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0421$t$, $t$Lawnside Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Resale / Rental)$t$, $j$["Issued by: Borough of Lawnside Construction Office (Construction Code Department)","Contact: 856-573-6214 · m.hauser@lawnside.net","Apply: Allow 10 business days for the inspection to be completed","How to apply: Fill out the Certificate of Occupancy Application (circle Resale) and submit it to the Construction Office, 4 Dr. Martin Luther King Jr. Road, with $75 per unit in cash, check or money order. Choose pick up, fax or email for the certificate. Repairs must be done within 30 days of the first inspection or a new application is needed.","Working smoke alarm on each level and in every bedroom","CO alarm within 10 feet of sleeping areas","ABC extinguisher (2.5 lb) mounted within 10 feet of the cooking area","Heater and roof certification from a NJ licensed contractor (resale only); a private home inspection or a new roof or heater under permit in the last 5 years is accepted instead","Heater/chimney connection secure; water heater relief valve pipe 2 to 6 inches from the floor","Sump pump may not discharge into the sewer line","Sidewalks and walkway to the house in good condition with no trip hazards","Graspable handrails on steps 24 inches or more above grade (both sides if 44 inches or wider); guardrails on decks and porches 24 inches or more above grade","GFCI outlets within 6 feet of sinks and along kitchen counters; all outlet and switch covers in place; no openings in the breaker panel","No water leaks; faucets working","Holes in walls and floors fixed; exposed wood painted inside and out","Trash and debris removed","House numbers visible from the street","All open construction permits completed and closed; no unresolved violation notices","Also: Open permits must be closed: All work under open construction permits must be completed and permits closed before the CO is issued.","Also: Heater and roof certification (resale only): From a NJ licensed contractor, or a private home inspection, unless a new roof or heater was installed under a UCC permit in the last 5 years."]$j$::jsonb, $j$[{"label":"CO inspection, per unit (includes initial inspection and one re-inspection)","amount":"$75.00"},{"label":"Additional re-inspection (after the included re-inspection, a missed re-inspection, or violations not fixed within 30 days)","amount":"$75.00"},{"label":"Fine for violations not corrected within 30 days, per day","amount":"$25"}]$j$::jsonb, $t$https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF$t$, $t$https://www.lawnside.net/1204/Construction-Department$t$, $j$[{"url":"https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF","label":"Official source (lawnside.net)"}]$j$::jsonb, $t$NOTE: This Dwelling Is Not To Be Occupied Until A Cerificate Of Occupancy Is Issued By The Construction Code Department Of The Borough Of Lawnside.$t$, $t$42984f77564966f84d43f42d18881e703ca033e25a58b54acd66be65c6639e2a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":5,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0421.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0421.json$t$, true),
  ($t$0421$t$, $t$Lawnside Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Borough of Barrington Bureau of Fire Prevention) (town fire bureau)","Contact: 856-547-0991 · firealliance@barringtonboro.com","Apply: Lowest fee with 14 or more business days notice before the change of occupant (weekends, holidays and the settlement date do not count)","How to apply: Fill out the Alliance's certificate application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox or mail it to 205 Haines Avenue, Barrington, NJ 08007. A check or money order payable to 'Regional Fire Prevention Alliance' must go with the application. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 5/19/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; take them down and check the date, replace if undated","Smoke alarm type by build year: pre-1975 homes need 10-year sealed battery alarms on each level; newer homes need hardwired, interconnected alarms per the year-built chart","Smoke alarm in each sleeping area plus one outside each sleeping area within 10 feet (local ordinance 172-8 B)","CO alarm outside of and near all sleeping areas if there is a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers: Arabic numerals at least 3 inches, contrasting, at least 60 inches above ground, visible from the street","Homes with a secondary power source (solar, generator, battery storage) need a printed label within 18 inches of the main panel and meter, like \"CAUTION MULTIPLE SOURCES OF POWER\"","Fire extinguisher (June 2025 form): fully charged 2-A:10-BC in or within 10 feet of the kitchen, visible, mounted no higher than 5 feet, and either under 1 year old or tagged by a NJ certified fire equipment contractor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8 to 13 business days before","amount":"$74.00"},{"label":"Request received 4 to 7 business days before","amount":"$106.00"},{"label":"3 business days or less notice","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF","label":"Official source (lawnside.net)"},{"url":"https://www.lawnside.net/DocumentCenter/View/464/Smoke-Alarm-Detector-Application-for-2025-PDF","label":"Official source (lawnside.net)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$febef68fd7229a023a762f6f2b62d324e0a5333217962f555546a7e38024c34c$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":5,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0421.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0421.json$t$, true),
  ($t$0422$t$, $t$Lindenwold Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO); Certificate of Transfer of Title (CTT) for vacant or rehab properties$t$, $j$["Issued by: Borough of Lindenwold Construction Office / Code Enforcement (Housing Clerk)","Contact: 856-783-2121 ext. 224 · hprotich@lindenwold.net","Apply: Not stated as a fixed deadline. The fee is lower if the inspection is scheduled 10 or more business days out. For a vacant CTT, call 5 to 7 business days before settlement for a pre-inspection.","How to apply: Fill out the one-page CCO application and submit it to the Code Enforcement Office at 15 N. White Horse Pike with a check or money order payable to the Borough of Lindenwold. Fees are per unit and nonrefundable. The Borough calls the listed contact to schedule after the permit and zoning search is done. A failed inspection needs a new application and fee before reinspection. For vacant or rehab properties, file the CTT and the CCO at the same time.","No open building or zoning permits (must be closed with fees paid)","No work done without a required construction or zoning permit","No unsafe structures or unsafe conditions","10-year sealed battery smoke alarm on every level and outside each sleeping area","CO alarm within 10 feet of sleeping areas","2A-10B:C fire extinguisher under 10 lbs, mounted within 10 ft of kitchen, tagged with current receipt","House numbers at least 4 inches, contrasting, fixed to the house and visible from the street","Handrails on 3 or more risers; guardrails on porches/decks 30 inches or higher","GFCI within 6 ft of water; no bare-wire fixtures","Heat, appliances (anti-tip on range), hot and cold water and toilets working","Water heater relief valve discharge pipe 2 to 6 inches from floor","Bathroom window or exhaust fan","No holes, flaking paint or water stains on walls, ceilings, floors; no roof leaks","Yard free of trash, debris and junk vehicles; all code violations abated","Utilities on at time of inspection","Also: Open permits must be closed: No open building or zoning permits; must be fully satisfied with fees and inspections before the CCO is issued.","Also: Work without permits: Unpermitted work (commonly finished basements, water heaters, furnaces) must be permitted and inspected before the CCO is issued.","Also: Zoning check: The Borough runs a zoning approval and permit search before scheduling the CCO inspection."]$j$::jsonb, $j$[{"label":"CCO inspection, 1-2 units, scheduled over 10 days out (form: 10 or more business days), per unit","amount":"$75"},{"label":"CCO inspection, scheduled less than 10 days out (form: 4 to 10 business days), per unit","amount":"$100"},{"label":"Re-inspection, per unit","amount":"$50"},{"label":"Administration fee for changing inspection date or unit number more than once","amount":"$20"},{"label":"Certificate of Transfer of Title (vacant property), includes one re-inspection within 120 days","amount":"$125"}]$j$::jsonb, $t$https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF$t$, $t$https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing$t$, $j$[{"url":"https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/141/Residential-Property-Sales---Inspection-Application--CTT-Certificate-of-Title-Transfer--for-Vacant-or-Rehab-Properties-PDF","label":"Official source (lindenwoldnj.gov)"}]$j$::jsonb, $t$All sales of a property must file for a certificate of occupancy (C/O) inspection for smoke detectors, carbon monoxide detectors, fire extinguishers, and house numbers.$t$, $t$e4f88bddf501b96bde5e1a043dbc36b5a1bead8a5dd65d5a07f8a7a795d3641e$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0422.json$t$, true),
  ($t$0422$t$, $t$Lindenwold Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lindenwold Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: 856-346-0935 · firemarshal@lindenwoldfire.com","Apply: Submit request 3 to 4 weeks before settlement","How to apply: Submit the online Residential Inspection Request Form on lindenwoldfire.com. Pay at the time of inspection by check or money order (no cash). The certificate is issued at the inspection if the home passes and payment is received. No temporary certificates.","Fire official in the NJ state directory (fire district), updated 5/26/2026: Timothy D Shannon · (856) 346-0935 · tshannon@lindenwoldfire.com","10-year sealed battery smoke alarm on every level; hardwired alarms cannot be replaced with battery alarms","Basement alarm at bottom of stairwell on the ceiling, not between joists","Bedroom hallway smoke alarms within 10 feet of all bedroom doors","Smoke and CO alarms less than 10 years old and working","CO alarm in hallway within 10 feet of all bedrooms; not in switched outlets","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers at least 4 inches, contrasting, fixed to the house, visible from the street or 50 feet (Borough Ordinance No. 757)","Homes with a secondary power source (solar, generator, battery storage) need a permanent printed label at the main panel and meter, e.g. \"Caution: Multiple Sources of Power\"","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$45.00"},{"label":"Request received 7 calendar days before settlement","amount":"$90.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$161.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.lindenwoldfire.com/FormCenter/General-Forms-4/Residential-Inspection-Request-Form-46$t$, $t$https://www.lindenwoldfire.com/182/Smoke-Carbon-Monoxide-Alarm-Compliance-C$t$, $j$[{"url":"https://www.lindenwoldfire.com/182/Smoke-Carbon-Monoxide-Alarm-Compliance-C","label":"Official source (lindenwoldfire.com)"},{"url":"https://www.lindenwoldfire.com/DocumentCenter/View/198/Residential-Resale-Requirements---","label":"Official source (lindenwoldfire.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$When selling a one or two family home in Lindenwold, you must obtain a Certificate of Smoke Alarm and Carbon Monoxide Detector Compliance CSACMAPFEC 5:70-2.3 (a) prior to the settlement. Please submit your request for inspection 3 to 4 weeks prior to the settlement date.$t$, $t$1cd6aba66e0cf7c34c5e8ae8a3c94a0e37a860074d4f1352cf684b1250fb7b15$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0422.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Certificate of Change in Ownership / Change in Occupancy), Borough Code Chapter 112$t$, $j$["Issued by: Borough of Magnolia Construction Office (building inspector or housing inspector)","Contact: 856-783-1520","How to apply: Fill out the Certificate of Continued Occupancy Application (linked from the Borough's \"Certificate of Change in Occupancy\" page, with an inspection checklist) and turn it in to the Construction Office, 438 W. Evesham Ave, Magnolia, with the $75.00 fee. An inspector will contact you to schedule. The owner or the owner's agent must apply.","Home must meet the property maintenance standards the Borough adopted (BOCA National Property Maintenance Code, 1993) and all Borough ordinances","Hard-wired, interconnected smoke detectors with battery backup on or near the ceiling of each level","Battery smoke detectors in each bedroom or sleeping area","Smoke detectors must be certified by the fire official or other authorized person before the certificate is issued","Any repairs needed for the certificate are the current owner's responsibility, even if the problem was caused by a previous owner","Under Ordinance 12-2026 (adopted Sept 2, 2026) the owner stays responsible until the certificate is issued, no matter what the sale contract, settlement or escrow agreement says; each day of violation after notice is a separate offense"]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy inspection when a home is sold (Borough page; same as Code 15.112-11 \"Change of property ownership, Residential\")","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-occupancy$t$, $j$[{"url":"https://web.archive.org/web/20260111210243/https://www.magnolia-nj.org/construction/page/certificate-change-occupancy","label":"Official source (web.archive.org)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/codes/code_of_ordinances?nodeId=TIT15BUCO_CH112CEOC_15.112-11FE","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/magnolia/ordinances/code_of_ordinances?nodeId=1442309","label":"Official source (library.municode.com)"},{"url":"https://www.magnolia-nj.org/construction/page/certificate-change-ownership","label":"Official source (magnolia-nj.org)"},{"url":"https://www.magnolia-nj.org/municipal-clerk/page/notice-final-adoption-ordinance-12-2026","label":"Official source (magnolia-nj.org)"}]$j$::jsonb, $t$Pursuant to Borough Code 17.270-31 Certificate of Occupancy Inspections are required whenever a home is being sold.$t$, $t$e3d88289924f856333fbcd8cba51d02342ee4c23691714381fa4911141fd77e9$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":4,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0423$t$, $t$Magnolia Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Magnolia Construction Office (smoke detector compliance) (town fire bureau)","Contact: 856-783-1520","Fire official in the NJ state directory (NJ DCA, state), updated 5/22/2026: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.magnolia-nj.org/construction/page/certificate-change-ownership$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$LEAID: 0423-999 Magnolia Boro SMOKE DETECTOR COMPLIANCE Enf Auth. State ... Name: Magnolia Boro Constr Office ... Addr: 438 West Evesham Av ... Magnolia NJ 08049 ... Fire Official Louis Kilmer NJ Div Fire Safety PO Box 809 ... Phone (856) 783-1520 Phone JUVENILE FIRESETTERS PROGRAM$t$, $t$15a8ef2048d26cacbc7c3bcb637378d16afe326b697e37d710d40b1c89b8b98b$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":4,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0423.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0423.json$t$, true),
  ($t$0424$t$, $t$Merchantville Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Inspection / Resale Certificate$t$, $j$["Issued by: Borough of Merchantville Code Enforcement (Office of Code Enforcement and Rental Housing Inspection)","Contact: 609-413-0010 · codeenforcement@merchantvillenj.gov","How to apply: Complete the Resale Inspection Application (includes the smoke detector certificate application) and bring it to the Borough Clerk's office at 1 W. Maple Avenue to pay the fee. Code Enforcement then contacts the applicant to schedule the inspection.","Valid for: 6 months after passed inspection","House numbers visible from the street","Fences, decks, sheds and accessory structures must have proper permits","Sidewalks and driveways level and free of trip hazards","Smoke alarm on each level including basement; 10-year sealed lithium battery type","CO detector within 10 feet of sleeping areas (plug-in or battery OK)","2A:10BC fire extinguisher in a cabinet or on a hanger within 10 feet of the kitchen","Handrail on stairs with more than 4 risers; guards on surfaces more than 30 inches above grade","Exterior surfaces painted or protected and in good repair","Yard free of excess weeds, rubbish and garbage","Accessory structures (garages, fences, walls) sound and in good repair","Pools clean; pools over 24 inches deep fenced at least 48 inches with self-closing, self-latching gates","Also: Permits for accessory structures: All fences, decks, sheds, and accessory structures must have proper permits."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$50.00"},{"label":"Resale re-inspection","amount":"$10.00"}]$j$::jsonb, $t$https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300$t$, $t$https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php$t$, $j$[{"url":"https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php","label":"Official source (merchantvillenj.gov)"},{"url":"https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300","label":"Official source (merchantvillenj.gov)"}]$j$::jsonb, $t$Before the sale of all residential properties, you are required to obtain a Resale Inspection, including smoke detector compliance. Please bring your completed application to the clerk's office with you to pay the required fee. The Applicant will be contacted to schedule an inspection.$t$, $t$74f5f0ace975924cbfc056fb8bf819d8f63e8ea20f9b815220ec8caab1ed1e08$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0424.json$t$, true),
  ($t$0424$t$, $t$Merchantville Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Merchantville Code Enforcement (Certificate of Smoke Detector Compliance) (town fire bureau)","Contact: 856-662-2474 ext. 310 · codeenforcement@merchantvillenj.gov","Apply: Fee is lowest if applied for more than 10 business days before settlement","How to apply: Fill out the Borough 'Application for Certificate of Smoke Detector Compliance' (page 3 of the resale packet) and submit it with the resale application at the Clerk's office with payment. The Code Enforcement Official schedules the inspection.","Fire official in the NJ state directory, updated 3/17/2026: Kevin Patti · (856) 662-0900 · kpatti@merchantvillenj.gov","Each smoke alarm must be a 10-year sealed lithium battery detector, on every level including basements","CO detector within 10 feet of sleeping areas","2A:10BC extinguisher in an approved cabinet or on a hanger within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before settlement","amount":"$35.00"},{"label":"Less than 10 days but more than 4 days","amount":"$70.00"},{"label":"4 business days or fewer","amount":"$125.00"},{"label":"Re-inspection, each","amount":"$10.00"}]$j$::jsonb, $t$https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300$t$, $t$https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php$t$, $j$[{"url":"https://www.merchantvillenj.gov/RESALE%20PAPERWORK%201-2026.pdf?t=202601211210300","label":"Official source (merchantvillenj.gov)"},{"url":"https://www.merchantvillenj.gov/government/code_enforcement_and_rental_inspection.php","label":"Official source (merchantvillenj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$BOROUGH OF MERCHANTVILLE APPLICATION FOR CERTIFICATE OF SMOKE DETECTOR COMPLIANCE$t$, $t$5e50de1b76d2499e392e576b131afcb5958e6993146a050a32ec8b2be881af6f$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0424.json$t$, true),
  ($t$0433$t$, $t$Tavistock Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Tavistock Borough requires a resale certificate. Call the office before closing.","Contact: 856-429-0039 · clerk@tavistocknj.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://tavistocknj.org/whos-who/$t$, $j$[{"url":"https://tavistocknj.org/wp-content/uploads/2025/05/2024-Tavistock-Minutes-12-19-2024.pdf","label":"Official source (tavistocknj.org)"}]$j$::jsonb, $t$Resolution #34-2024 Authorizing Shared Service Agreement with Haddonfield - Construction$t$, $t$e29a39aa4bab30d925f62a77523bd89caad711111454c0103c8ea5f8e4cdb372$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0433.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0433$t$, $t$Tavistock Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haddonfield Bureau of Fire Prevention (serving Tavistock under a shared service agreement) (town fire bureau)","Contact: 856-429-4308 · ebusch@haddonfield-nj.gov","How to apply: Contact the Haddonfield Fire Official (Ernest F. Busch) or the Haddonfield Construction and Zoning Office, Room 104, Haddonfield Borough Hall, which receives smoke detector compliance forms and payment for Haddonfield. Confirm the Tavistock process and fee before applying.","Fire official in the NJ state directory (town), updated 5/18/2026: Ernest F Busch · (856) 429-4308 · ebusch@haddonfield-nj.gov","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php$t$, $j$[{"url":"https://tavistocknj.org/wp-content/uploads/2025/05/2024-Tavistock-Minutes-12-19-2024.pdf","label":"Official source (tavistocknj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Resolution #33-2024 Authorizing Shared Service Agreement with Haddonfield - Fire Services$t$, $t$32289d3f06f96ad625972dda57860410a519cb0676b6b7e5404350c18009cd41$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0433.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0435$t$, $t$Waterford Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Reoccupancy Inspection (Residential Resale Inspection); Certificate of Inspection$t$, $j$["Issued by: Waterford Township (form posted by the Construction & Zoning Enforcement office; inspections under the Township fire official)","Contact: 856-768-2300 ext. 307 · fireofficial@waterfordtwp.org","Apply: Apply at least 10 days before settlement for the lowest fee","How to apply: Fill out the Residential Reoccupancy Form (block, lot, settlement date, lock box code and location, owner, buyer and realtor contacts) and submit it to Waterford Township, 2131 Auburn Ave, Atco, NJ 08004. Pay by cash, check or money order. Include passed water and septic certifications.","Valid for: 30 days","Smoke alarm on each floor including the basement and within 10 feet of a bedroom","Battery smoke alarms must be 10-year sealed; hardwired (110 volt) alarms cannot be replaced with battery alarms","Smoke alarms less than 10 years old (or per manufacturer replacement date)","Carbon monoxide alarm within 10 feet of a bedroom, less than 5 years old (or per manufacturer)","House number visible from the street, 3 to 6 inches tall","Passed water and septic certifications must be submitted before the certificate is released","A house with a cesspool cannot be sold until a septic system is installed; if a new system is needed, show money in escrow","Secondary power (meter and electrical panels) and all utilities on and working (listed on the 2025 form)","No bulk trash or debris left at the property or curb (2025 form says the certificate will not be issued otherwise)","Do not take Township trash and recycling carts","Uninhabitable 'as is' sales need a notarized letter and are referred to the Construction Office (2025 form)","Also: Water and septic certifications: Passed water and septic certifications must be submitted before the Township releases the certificate (mark public water, private well, public sewer or septic).","Also: Cesspool replacement: A house with a cesspool cannot be sold until a septic system is installed; if a new system is needed, proof of escrowed funds is required."]$j$::jsonb, $j$[{"label":"Inspection, applied 10 days before settlement","amount":"$75"},{"label":"Inspection, applied 4 to 9 days before settlement","amount":"$125"},{"label":"Inspection, applied 2 to 3 days before settlement","amount":"$200"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf$t$, $t$https://waterfordtwp.org/departments/construction-zoning-enforcement/$t$, $j$[{"url":"https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf","label":"Official source (waterfordtwp.org)"},{"url":"https://waterfordtwp.org/wp-content/uploads/2025/08/Scanner@Waterfordtwp.org_20250820_102823.pdf","label":"Official source (waterfordtwp.org)"}]$j$::jsonb, $t$***PASSED WATER AND SEPTIC CERTIFICATIONS MUST BE SUBMITTED BEFORE WE RELEASE CO***$t$, $t$add18ae1162dce1dd5c75a62f3a31995a49e3a279c47ba16bb18a09efb53a13b$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":6,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0435.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0435.json$t$, true),
  ($t$0435$t$, $t$Waterford Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Waterford Township Fire Prevention (municipal local enforcing agency, Fire Official Craig Fallstick) (town fire bureau)","Contact: 856-768-2300 · fireofficial@waterfordtwp.org","Apply: Apply at least 10 days before settlement for the lowest fee; certificate good for 30 days","How to apply: Use the Township Residential Reoccupancy Form; the smoke and CO alarm certificate is issued from that inspection.","Fire official in the NJ state directory (town), updated 8/17/2026: Craig Fallstick · (856) 768-2300 · fireofficial@waterfordtwp.org","Smoke alarms less than 10 years old (or per manufacturer replacement date)","Carbon monoxide alarms less than 5 years old (or per manufacturer replacement date)","Battery smoke alarms must be 10-year sealed; hardwired alarms cannot be swapped for battery units","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Same combined resale/reoccupancy inspection fee, applied 10 days before settlement (pay once)","amount":"$75"},{"label":"Same combined inspection fee, applied 4 to 9 days before settlement (pay once)","amount":"$125"},{"label":"Same combined inspection fee, applied 2 to 3 days before settlement (pay once)","amount":"$200"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf$t$, $t$https://waterfordtwp.org/departments/construction-zoning-enforcement/$t$, $j$[{"url":"https://waterfordtwp.org/wp-content/uploads/2026/08/Reoccupy-APPLICATION.pdf","label":"Official source (waterfordtwp.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Inspection will only be issued when the premises meet the minimum requirements of the New Jersey State Uniform Fire Code, N.J.A.C. 5:70-4:19.$t$, $t$8686371fb0b1b3a14a0aa294b700cfa38efc856310f833fecf3a4274cff038a3$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":6,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0435.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0435.json$t$, true),
  ($t$0437$t$, $t$Woodlynne Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection for Resale$t$, $j$["Issued by: Borough of Woodlynne Construction Official","Contact: 856-962-8300 ext. 219 · woodlynnedavid@comcast.net","How to apply: Fill out the Application for Certificate of Inspection for Resale (address, owner, agent, emergency contact) and return it to the Borough of Woodlynne, 200 Cooper Ave., Woodlynne, NJ 08107, or fax it to 856-962-8763. Contact David Munoz at 856-962-8300 ext. 219.","Inspection for resale is marked pass or fail by the Construction Official","Any building, plumbing, electrical or fire permits the Construction Official requires must be completed before the final Certificate of Occupancy"]$j$::jsonb, $j$[{"label":"Application fee","amount":"$96.00"}]$j$::jsonb, $t$https://www.woodlynnenj.org/_files/ugd/b7bd99_79e91dc4d3fa4e6a9fcbfd5848ff3881.pdf$t$, $t$https://www.woodlynnenj.org/code-enforcement$t$, $j$[{"url":"https://www.woodlynnenj.org/_files/ugd/b7bd99_79e91dc4d3fa4e6a9fcbfd5848ff3881.pdf","label":"Official source (woodlynnenj.org)"},{"url":"https://www.woodlynnenj.org/code-enforcement","label":"Official source (woodlynnenj.org)"}]$j$::jsonb, $t$Application for Certificate of Inspection for Resale$t$, $t$afc2f014c99884691b3c2547c41675f030de8ff43ea8a668fb326192c7ffa992$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":6,"q_ok":4,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0437.json$t$, true),
  ($t$0437$t$, $t$Woodlynne Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: 609-633-6106","How to apply: Apply and pay online through the NJ DCA service portal using 'Apply for Smoke Certification'.","Fire official in the NJ state directory (NJ DCA, state), updated 3/14/2023: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, application more than 10 business days before change of occupant (state fee rule, 2017)","amount":"$45.00"},{"label":"Smoke/CO certificate, application 4 to 10 business days before change of occupant (state fee rule, 2017)","amount":"$90.00"},{"label":"Smoke/CO certificate, application fewer than 4 business days before change of occupant (state fee rule, 2017)","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/adopted_amendment_5_10_2.9.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$WOODLYNNE BORO 0437 SC$t$, $t$1b07455fdcef50dd8ab38a2241ec97ce3f733cac148fb309db11f4756b552ba2$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":6,"q_ok":4,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0437.json$t$, true),
  ($t$0808$t$, $t$Harrison Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Transfer of Ownership / Occupancy (CTO)$t$, $j$["Issued by: Harrison Township Housing Department (Housing Code Official, Property Maintenance / Code Enforcement)","Contact: 856-478-4111 · property_maintenance@harrisontwp.us","Apply: Apply at least 30 days before settlement. Inspections requested within 10 business days of the application are charged the expedited fee.","How to apply: Fill out the CTO application completely and submit it with the fee (cash or check) to the Housing Code Official's office, 114 Bridgeton Pike, Mullica Hill. Inspectors in the field will not accept applications or fees. After the application is processed, the owner or realtor must call or email the housing office to schedule the inspection. If the buyer is taking responsibility for the certificate, the office must be told in writing before the CTO is issued.","Passing inspection under the 2024 International Property Maintenance Code","Smoke detector certification from the fire department (Fire District #1)","Septic certification; if work is needed, written documentation or sealed correction plans, with 60 days to fix under a temporary certificate","Proper permits and inspections for any work done in the home","All utilities on and working at the time of inspection","Certifications may be required for chimneys, roof, electrical, structural and heating","Also: Septic certification: Required for issuance of the CTO; if the septic is not certified and work is needed, submit written documentation or sealed correction plans; 60 days to correct under a Temporary Certificate.","Also: Open permits: Proper permits and inspections are required for any work completed in the home.","Also: Utilities on: All utilities must be on and working at the time of inspection."]$j$::jsonb, $j$[{"label":"Residential initial inspection (covers initial inspection and first re-inspection)","amount":"$100.00"},{"label":"Residential expedited (inspection needed within 10 business days of application)","amount":"$150"},{"label":"Third and each later inspection","amount":"$50.00"}]$j$::jsonb, $t$https://harrisontwp.us/wp-content/uploads/2025/11/CTO-applicatiCertification-of-Tranfer-of-OwnershipOccupancy-Application-rev-11242025.pdf$t$, $t$https://harrisontwp.us/department/property-maintenance-code-enforcement/$t$, $j$[{"url":"https://harrisontwp.us/wp-content/uploads/2025/11/CTO-applicatiCertification-of-Tranfer-of-OwnershipOccupancy-Application-rev-11242025.pdf","label":"Official source (harrisontwp.us)"}]$j$::jsonb, $t$PROPERTY TYPE: ____House Sale / ____ House Rental / ____ Apartment Rental / _____ Commercial ... Please do not schedule a settlement date until the CTO is approved and returned.$t$, $t$20fc64665b02debe6b66e0e498333822f533cced332e64c1601a19ee481bbf2c$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0808.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0808.json$t$, true),
  ($t$0808$t$, $t$Harrison Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bureau of Fire Prevention, Harrison Township Fire District #1 (fire district)","Contact: 856-478-0423 · matt@htfd23.com","Apply: Lowest fee applies when the request is received 11 or more days before closing","How to apply: Fill out the Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance application (mark Sale, give closing date) and send it with a check payable to 'Bureau of Fire Prevention' to Harrison Township Fire District #1, 312 Ewan Rd, Mullica Hill, NJ 08062, or contact the office by email.","Fire official in the NJ state directory (fire district), updated 8/23/2012: Matthew R Cardile · (609) 868-0823 · matt@htfd23.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 11 or more days before closing","amount":"$90.00"},{"label":"Request received 5 to 10 days before closing","amount":"$160.00"},{"label":"Request received 4 days or less before closing","amount":"$200.00"},{"label":"Re-inspection for failed inspection","amount":"$65.00"}]$j$::jsonb, $t$https://harrisontwp.us/wp-content/uploads/2024/01/Fire-inspection-revised-01032024.pdf$t$, $t$https://harrisontwp.us/department/fire-district/$t$, $j$[{"url":"https://harrisontwp.us/wp-content/uploads/2024/01/Fire-inspection-revised-01032024.pdf","label":"Official source (harrisontwp.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any one- and two-family or attached single family structure is sold, leased, or otherwise made subject to a change of occupancy for residential purposes, the owner shall obtain a certificate or smoke alarm, carbon monoxide alarm, and portable fire extinguisher compliance CSACMAPFEC, evidencing compliance with N.J.A.C. 5:70-4.19$t$, $t$d438f1c3b1ac64618563bb3165380450bfa183a794c8d0cf032dc3903ea0bfb2$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0808.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0808.json$t$, true),
  ($t$0818$t$, $t$Washington Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale (Certificate of Resale)$t$, $j$["Issued by: Washington Township Housing Office (Division of Community Development, in the Construction Office)","Contact: 856-589-0520 ext. 2231 or 2296 · vorr@twp.washington.nj.us","Apply: Have the inspection done at least 3 weeks before settlement (Housing FAQ). Expedited inspections are available for an added fee.","How to apply: Fill out every field of the Application for Certificate of Occupancy - Sale and submit the original with a wet ink signature (DocuSign is not accepted) plus the fee by check or cash payable to Township of Washington, to the Housing Office, Municipal Building, 523 Egg Harbor Road, Sewell. The office assistant schedules an AM or PM inspection window. The seller's agent may apply. No one needs to be home if the inspector can get in (lock box code or key left on the property; no loose pets). Pass: the CO is emailed. Fail: the report is emailed; fix items and call to schedule the reinspection.","House number plainly visible from the street, at least 4 inches high","Sidewalk free of trip hazards","Roof drains, gutters and downspouts in good repair","Windows and doors open easily and stay in place","Stairs, decks, porches and balconies permitted and structurally sound; guards over 30 inches; graspable handrails","Pool fully fenced with self-closing, self-latching gates that open outward","Exit doors open from inside without a key (no double-keyed deadbolts)","No more than 2 persons per bedroom; lofts cannot be bedrooms","Smoke detector on every level; hardwired stays hardwired, otherwise 10-year sealed battery","Carbon monoxide detector near all sleeping rooms","All utilities (electric, water, gas) on for the inspection","Water heater with proper temperature/pressure relief valve and discharge pipe (permit required)","Safe electrical system and covers; no hazards","Dryer exhaust vented outside in non-combustible material; bath fan or window vented outdoors","No plumbing leaks; fire-rated walls and ceilings intact; attic access; all open permits closed","Also: Open permits must be closed: Permits must be completed with the Construction Office in order to pass inspection; unpermitted work must be fixed before the CO is issued.","Also: Temporary Certificate of Occupancy (TCO): If the buyer agrees to take on repairs, a notarized Affidavit for TCO lets settlement go ahead; the fee ordinance lists $125 for a TCO request after the initial inspection.","Also: Well and septic: The sale application asks whether the home has a private well, private septic, Township water or Township sewer; the Housing page links to Gloucester County well and septic records. No sale-time well or septic test requirement was found."]$j$::jsonb, $j$[{"label":"Initial inspection, sale (includes smoke certification and 1st reinspection)","amount":"$150"},{"label":"Expedited inspection, within 2 days (added fee)","amount":"$100"},{"label":"Expedited inspection, 3-5 days (added fee)","amount":"$75"},{"label":"Fee ordinance: CO inspection portion, first two inspections (plus expedited add-ons)","amount":"$125"},{"label":"Reinspection, each (form: each additional after the included 1st reinspection)","amount":"$75"},{"label":"Temporary certificate of occupancy (TCO) request, after initial inspection","amount":"$125"},{"label":"Penalty for occupying without a certificate of occupancy (listed under Change in occupancy, § 179-73)","amount":"$100"}]$j$::jsonb, $t$https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf$t$, $t$https://www.twp.washington.nj.us/departments/housing/index.php$t$, $j$[{"url":"https://www.twp.washington.nj.us/departments/housing/index.php","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/departments/housing/faqs.php","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/O017-2026%20Ordinance%20Amending%20Chapter%2080%20Fees.pdf","label":"Official source (twp.washington.nj.us)"}]$j$::jsonb, $t$179- 68. Certificates of occupancy shall be required for human habitation of all existing dwelling units in the Township of Washington before a change in occupancy or change of owner may be effected.$t$, $t$3d62d2a743b9d07293d4704c2e80e7cb2db20335eb38eb4e7a0334969892f475$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":4,"fee_bad":0,"fee_unchecked":5,"quotes":10,"q_ok":8,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0818.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0818.json$t$, true),
  ($t$0818$t$, $t$Washington Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire township: issued by Washington Township Housing Office (smoke certification included in the Certificate of Occupancy - Sale) (town fire bureau)","Entire township contact: 856-589-0520 ext. 2231 or 2296 · vorr@twp.washington.nj.us","Entire township, apply: At least 3 weeks before settlement (Housing FAQ)","Entire township, how to apply: Apply for the Certificate of Occupancy - Sale with the Housing Office; the $150 initial fee includes the smoke certification. No separate smoke certificate application was found.","Fire District No. 1: issued by Washington Township Fire District No. 1 (Washington Township Fire Department) (fire district). Covers: Entire township (the only fire district in Washington Township)","Fire District No. 1, how to apply: Not found. The district website (wtfd10.com, linked from the Township site as Fire Department) returned a bot-check page and could not be read.","Fire official in the NJ state directory (fire district), updated 6/16/2026: Michael Mitten · (856) 863-4000 · mmitten@wtfd10.org","Smoke detector on every level; hardwired alarms must stay hardwired; non-hardwired alarms must be 10-year sealed battery (Township checklist)","Carbon monoxide detector in the vicinity of all sleeping rooms","Homes with a generator, solar panels or battery storage need a 'multiple sources of power' label within 18 inches of the main electrical panel and meter (state law P.L.2025, c.19, posted by the Township, enforced at change of occupancy from 3/10/25)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Entire township: Smoke Certificate (fee ordinance)","amount":"$25"},{"label":"Entire township: Sale CO initial inspection, which includes smoke certification","amount":"$150"}]$j$::jsonb, $t$https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf$t$, $t$https://www.twp.washington.nj.us/departments/housing/index.php$t$, $j$[{"url":"https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Inspection%20Checklist%20July%202026.pdf","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Secondary%20Power%20Source%20Identification%20Label%20Memo.pdf","label":"Official source (twp.washington.nj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/divisions/dlgs/programs/lpcl_docs/cd_gloucester.docx","label":"Official source (nj.gov)"},{"url":"https://www.twp.washington.nj.us/O017-2026%20Ordinance%20Amending%20Chapter%2080%20Fees.pdf","label":"Official source (twp.washington.nj.us)"}]$j$::jsonb, $t$$150 - Initial Inspection Fee (includes smoke certification and 1st Re- Inspection)$t$, $t$12c406aa98e9d79df4a67c72c6cd3dd332be05415ce5c749066b856f0b5eb896$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":4,"fee_bad":0,"fee_unchecked":5,"quotes":10,"q_ok":8,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0818.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0818.json$t$, true),
  ($t$1108$t$, $t$Pennington Borough$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Pennington Borough. Confirm with the office if the buyer's lender or title company asks.","Contact: Rick Smith, Superintendent of Public Works (schedules the pre-closing water and sewer House Inspection) · 609-737-9440 · publicworks@penningtonboro.org","How to apply: No Borough Certificate of Occupancy is needed for a sale. Separately, the Borough requires a Department of Public Works water and sewer House Inspection before closing (see the \"Also\" lines) and a final meter read.","Also: Water and sewer House Inspection by the Department of Public Works (required before closing): Schedule at least ten business days before closing with Superintendent of Public Works Rick Smith, 609-737-9440. Ordinance 2026-19, adopted June 1, 2026 (adoption vote recorded in the June 1, 2026 Council minutes), sets the fee: \"House inspections on sale of property: regular fee, $150 $200; fee if less than 10 days' notice, $250 $300.\" ($150 and $250 struck, $200 and $300 new.) The Home Sale Checklist says the House Inspection fee is charged to the final water/sewer bill, while the older Water/Sewer page still says \"There is a fee of $100 that must be either mailed or dropped off at Borough…","Also: Water/Sewer page (older House Inspection fee wording): Quote: \"A water and sewer inspection is required before the closing date of the sale of your house.\" The same page still lists a $100 fee paid before the inspection, which does not match Ordinance 2026-19.","Also: Final water meter read: Once there is a closing date, email Gabrielle Smith, DPW (publicworks@penningtonboro.org), with the title company name. The non-quarterly meter read fee is charged to the final water/sewer bill; Ordinance 2026-19 (adopted June 1, 2026) sets \"Scheduled: $75 $100; urgent/disputed: $100 $150\" ($100 scheduled, $150 urgent)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist$t$, $j$[{"url":"https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/DocumentCenter/View/1717/Sale-of-Home","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/1242/WaterSewer","label":"Official source (penningtonboro.org)"}]$j$::jsonb, $t$The Borough does not require a Certificate of Occupancy for the sale of a residential property.$t$, $t$ef91f0294ca599a5e6b58d1c31b0797a1cf11d6e9b0371a53a31158e9cee0a36$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1108.json$t$, true),
  ($t$1108$t$, $t$Pennington Borough$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency and issues smoke certificates in Pennington) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official for Pennington in the state directory (Bureau Chief, Bureau of Fire Code Enforcement) · 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply and pay online through the NJ DCA Fire Safety Service Portal ('Start Your Smoke Certification Application'), as the Borough checklist directs. Pay by e-check or credit card before submitting; a valid email is required and the certificate is emailed once the fee is paid and any required inspection is done. Homes heated only by electricity with no attached garage (no CO alarm needed) should email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 6/4/2026: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State fee: Request received more than 10 business days before the change of occupant (N.J.A.C. 5:70-2.9(d))","amount":"$45.00"},{"label":"State fee: Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"State fee: Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/DocumentCenter/View/1710/Ordinance-2026---3---Changing-Enforcement-Agencies-Under-Fire-Codedocx","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/DocumentCenter/View/1827","label":"Official source (penningtonboro.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Inspection Services - Request services, schedule appointments, and pay fees 24/7 through the DCA website at$t$, $t$220007f795db35150fd134707a94f0e1b66db69d406decda734a0087e9b74451$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":1,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1108.json$t$, true),
  ($t$1204$t$, $t$East Brunswick Township$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per East Brunswick Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Steven R. Curtis, Construction Official · 732-390-6875 · scurtis@eastbrunswick.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.eastbrunswick.org/162/Continued-Certificate-of-Occupancy-Requi$t$, $j$[{"url":"https://www.eastbrunswick.org/162/Continued-Certificate-of-Occupancy-Requi","label":"Official source (eastbrunswick.org)"},{"url":"https://www.eastbrunswick.org/158/Construction-Inspection","label":"Official source (eastbrunswick.org)"}]$j$::jsonb, $t$Note: By Ordinance, East Brunswick Township does not require or issue a Certificate of Occupancy for residential resale or rentals.$t$, $t$3a8398d81cd1034f945213e607ea691d94b1b084669246f4a49ab00f077f178f$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":23,"q_ok":17,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1204.json$t$, true),
  ($t$1204$t$, $t$East Brunswick Township$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["East Brunswick Bureau of Fire Safety, Fire…: issued by East Brunswick Bureau of Fire Safety, Fire Districts #1 and #3 (Fire Marshal's Office) (fire district). Covers: Homes in East Brunswick Fire District #1 or Fire District #3 (District #1 is the enforcing agency for District #3). District #3 is described by its fire company as about 4 square miles in the…","East Brunswick Bureau of Fire Safety, Fire… contact: Jaysen A. Whalen, Fire Marshal, Bureau of Fire Safety, East Brunswick Fire Dist. #1 & #3 · 732-651-8806 · JWhalen@ebfmo.org","East Brunswick Bureau of Fire Safety, Fire…, apply: Request at least two weeks before the closing or rental date; lowest fee when scheduled more than 10 days before closing","East Brunswick Bureau of Fire Safety, Fire…, how to apply: Use the online SMOKE/CO INSPECTION REQUEST form on the Fire Marshal's Office website (address, owner, buyer or tenant, requester email and phone, closing/rental date). Pay by credit card through the payment link on the site (debit cards not accepted). Questions: CSmith@ebfmo.org or 732-651-8806.","Fire District #2: issued by East Brunswick Fire District #2 Bureau of Fire Prevention (fire district). Covers: Homes in East Brunswick Fire District #2 (served by the East Brunswick Independent Fire Company)","Fire District #2 contact: 732-210-4582 · administrativeassistant@ebfd2.org","Fire District #2, apply: Ten or more business days before closing for the lowest fee; certificate valid six months","Fire District #2, how to apply: Download the Smoke Alarm Inspection Application from the District #2 Fire Prevention Forms page. Email it to administrativeassistant@ebfd2.org or bring it to 216 Joseph Street (William Peck Annex), East Brunswick. Checks payable to E.B. Bureau of Fire Prevention, Dist. 2; credit cards accepted (the Payments page has a pay link; include your invoice number). Inspections are Monday, Wednesday and Friday, 4:00 to 6:00 PM, and the certificate is issued on the spot when the home passes.","Fire official in the NJ state directory (fire district), updated 2/6/2026: Jaysen A Whalen · (732) 651-8806 · fireofficial@ebfmo.com","Districts 1 and 3: working hardwired or 10 year sealed battery smoke detector on each floor including the basement near the stairs, and within 10 feet of each bedroom; hardwired detectors must stay hardwired; detectors over 10 years old must be replaced; UL listed","Districts 1 and 3: a low voltage fire alarm system needs a passing inspection report from the alarm company, a NJ-certified fire protection contractor or a licensed electrician, shown to the inspector","Districts 1 and 3: CO detector in the hallway within 10 feet of any bedroom if the home has a fuel burning appliance or attached garage; stand-alone CO detectors no more than 7 years old, combination smoke/CO no more than 10 years old","Districts 1 and 3: house numbers at least 4 inches high (or at least 2 inches on both sides of a curbside mailbox), visible from the street and contrasting","District 2: alarm type depends on year built (before 1977 10 year sealed battery; 1977 to 1984 electric; 1984 to 1990 electric interconnected; after 1990 electric interconnected with battery back-up and one in each bedroom); CO alarm within 10 feet of each sleeping area","District 2: secondary power sources (solar, generator, etc.) must be properly labeled (new February 2025)","All districts: portable fire extinguisher recommended, not required (since February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"East Brunswick Bureau of Fire Safety, Fire…: Smoke/CO inspection scheduled more than 10 days before closing","amount":"$50.00"},{"label":"East Brunswick Bureau of Fire Safety, Fire…: Scheduled 4 to 10 days before closing","amount":"$75.00"},{"label":"East Brunswick Bureau of Fire Safety, Fire…: Scheduled 4 days or less before closing","amount":"$125.00"},{"label":"Fire District #2: Smoke/CO inspection, ten or more business days before closing","amount":"$50.00"},{"label":"Fire District #2: Less than ten business days before closing","amount":"$75.00"},{"label":"Fire District #2: Less than four business days before closing","amount":"$125.00"},{"label":"Fire District #2: Re-inspection for a failed inspection","amount":"$20.00"},{"label":"Fire District #2: No-show for a scheduled inspection without notice","amount":"$75.00"}]$j$::jsonb, $t$https://www.ebfmo.org/smoke-form.php$t$, $t$https://www.ebfmo.org/$t$, $j$[{"url":"https://www.ebfmo.org/","label":"Official source (ebfmo.org)"},{"url":"https://www.ebfmo.org/smoke-form.php","label":"Official source (ebfmo.org)"},{"url":"https://www.ebfmo.org/form/SmokeCOExtinguisherGuidelines03.pdf","label":"Official source (ebfmo.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.brookviewfire.com/","label":"Official source (brookviewfire.com)"},{"url":"https://firebasestorage.googleapis.com/v0/b/ebfd2-61921.appspot.com/o/forms%2FSmoke%20Alarm%20Inspection%20Application.pdf?alt=media&token=d21889d2-eeec-42d8-910e-a0c45b5440de","label":"Official source (firebasestorage.googleapis.com)"},{"url":"https://www.ebfd2.org/fireprevention/about","label":"Official source (ebfd2.org)"}]$j$::jsonb, $t$Residents of East Brunswick Fire District 1 and 3 selling or renting their home will need a “Certificate of Smoke alarm, carbon monoxide alarm” (CSACMAC).$t$, $t$efd8025df93904469813a51fb62d17980806ebafa152e5d9d931a10c470b9513$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":23,"q_ok":17,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1204.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Continued Use (combined certificate of smoke alarm, carbon monoxide alarm and compliance, CSDCMAC)$t$, $j$["Issued by: Borough of Eatontown inspector (Housing Official, Code Enforcement Officer, Fire Marshal or Fire Inspector)","Contact: Nicholas Cosentino, Housing Officer · 732-389-7616 · housing@eatontownnj.com","Apply: Fees rise when the request is made 10 or fewer business days before the change of occupancy. All fees are paid with the application before any inspection.","How to apply: Apply in writing to the Borough inspector (Housing Division, 47 Broad Street) with the buyer's information and pay the fee with the application. The inspector issues the certificate if no violations exist; otherwise the owner is told in writing what must be fixed. No online application form was found on the Borough website.","Valid for: 60 days (Code §116-6B); the code also says CSDCMAC inspections are valid for six months","Inspection for fitness for habitation under Borough Code §116-8 before the home is sold","Any outstanding permit issues must be closed; Zoning Officer certifies compliance","Smoke detectors on each level and within 10 feet of sleeping quarters, working and under 10 years old; 10-year sealed battery units; AC powered units cannot be swapped for battery units","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","Monitored fire alarm systems must be made available for testing, with a certificate of inspection","Checklist items include working doors and keyless deadbolts, GFCI in bathrooms, covered electrical boxes and plates, 4-inch house numbers, handrails on stairs over four risers, unbroken operable windows, safe sidewalk/driveway/apron/foundation, heating system and flue, water heater overflow pipe, metal dryer vent, minimum 60 amp service, sump pump on a dedicated receptacle","Application states the future owner's name and address and who will allow entry","Also: Open permits and zoning: Outstanding permit issues must be closed and the Zoning Officer must certify compliance before the certificate is issued."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"},{"label":"Transfer of residential properties (lawful two-family homes charged separately)","amount":"$200"},{"label":"Buyer backs out and a new buyer purchases before occupancy (updated application)","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/161/Building-Construction$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/161/Building-Construction","label":"Official source (eatontownnj.com)"}]$j$::jsonb, $t$Eatontown Borough shall perform inspections in accordance with the New Jersey Uniform Fire Code before any one- and two-family or attached single-family structure is sold, leased, or otherwise made subject to a change of occupancy for residential purposes.$t$, $t$c98535a97f8a7cb4d187a4d31a4d8062a47520bc0ecfa140c59c0d0bc4d65bbb$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eatontown Housing Division and Bureau of Fire Safety (combined certificate of occupancy and CSDCMAC) (town fire bureau)","Contact: Patrick A. Renaldi, Fire Marshal · 732-389-7620 · prenaldi@eatontownnj.com","Apply: Combined with the certificate of occupancy inspection; fee depends on business days before the change of occupancy.","How to apply: The smoke/CO certificate is not applied for separately: Eatontown issues one combined certificate after its habitability inspection (see resale certificate).","Fire official in the NJ state directory, updated 10/2/2024: Patrick Renaldi · (732) 389-7621 · prenaldi@eatontownnj.com","Smoke detectors on each level and within 10 feet of sleeping quarters, working and less than 10 years old","10-year sealed battery single station smoke alarms (ANSI/UL 217); AC powered alarms from original construction or rehabilitation stay AC powered","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","No fire extinguisher for owner sales; the code lists extinguishers for rental and apartment units only","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/194/Bureau-of-Fire-Safety$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/194/Bureau-of-Fire-Safety","label":"Official source (eatontownnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$To protect the health, safety, and wellness of all residents and first responders, the owner shall obtain a combined certificate of smoke alarm, carbon monoxide alarm, and compliance.$t$, $t$7ea2a858b63a558095796221e4aec80a61631eb45bb1a650e21afeccbc00b4eb$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1513$t$, $t$Lacey Township$t$, $t$OCEAN$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Construction Office, Department of Community Development. Confirm with the office if the buyer's lender or title company asks.","Issued by: Construction Office, Department of Community Development","Contact: Christopher Reid, Director, Community Development (department that runs the Construction Office) · 609-693-1100, ext. 2253 · lacey.commdev@laceytownship.org","Apply: Allow 14 business days for the Letter of No Interest","How to apply: Download the Request for Letter of No Interest, fill in the block, lot, address, requester and closing date, and submit it with the $50 fee (cash, or check payable to the Township of Lacey) to the Construction Office, 124 South Main Street, Forked River (mail to 818 Lacey Road). Faxed requests are not accepted. The letter can be mailed, picked up or emailed. Allow 14 business days.","No open construction permits (the Letter of No Interest confirms this for the buyer)","Also: Letter of No Interest (no open permits): Required instead of a resale CO; $50, allow 14 business days; confirms there are no open permits on the house."]$j$::jsonb, $j$[{"label":"Letter of No Interest (required instead of a resale certificate of occupancy)","amount":"$50"}]$j$::jsonb, $t$https://www.laceytownship.org/DocumentCenter/View/243$t$, $t$https://www.laceytownship.org/1207/Building-Department$t$, $j$[{"url":"https://www.laceytownship.org/1207/Building-Department","label":"Official source (laceytownship.org)"},{"url":"https://www.laceytownship.org/DocumentCenter/View/243","label":"Official source (laceytownship.org)"},{"url":"https://www.laceytownship.org/m/directory/department?did=11","label":"Official source (laceytownship.org)"}]$j$::jsonb, $t$Lacey Township does not require a Certificate of Occupancy for resale. Lacey Township does require a Letter of No Interest .$t$, $t$e09a7a6ada7db1a09f10484322615c9d796bd8f3a04937a04ab3eefaa9efdc35$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1513.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1513.json$t$, true),
  ($t$1513$t$, $t$Lacey Township$t$, $t$OCEAN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety, Deputy Division Director) · 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee; a new application is needed if the change of occupant does not happen within 6 months","How to apply: Apply online on the NJ DCA Fire Safety portal (the Township's Building Department page links to it). The applicant checks off each smoke alarm, CO alarm and power source label requirement and pays by e-check or credit card before submitting. The certificate is emailed once the fee is paid and any required inspection is done. Homes heated by electricity with no CO requirement should email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 5/19/2025: Louis Kilmer · (609)633-6132","CO alarms within about 10 feet of sleeping areas when the home has a fuel-burning appliance or attached garage (battery, hardwired or plug-in allowed)","State online form (CSACMASPSIL) covers smoke alarms, CO alarms and the secondary power source label; no fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State fee: Request received more than 10 business days before the change of occupant (N.J.A.C. 5:70-2.9(d))","amount":"$45.00"},{"label":"State fee: Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"State fee: Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.laceytownship.org/1207/Building-Department","label":"Official source (laceytownship.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Single-Family Dwelling Resale When selling your home, a smoke detector certification is required through the State of New Jersey.$t$, $t$a0e460525406ac4ec14e69a9ab296ade375b6f26839e26a572a525f3d25662ba$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1513.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1513.json$t$, true),
  ($t$1602$t$, $t$Clifton City$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Dwelling Certificate (Certificate of Inspection for 1 & 2 family dwellings, sale)$t$, $j$["Issued by: Clifton Fire Department, Fire Prevention Bureau, after Building, Tax and Zoning Department sign-off","Contact: Michael Pressler, Fire Marshal (Building Department open-permit check: Ernest Tedesco, Construction Official, 973-470-5809) · (973) 470-5801 · mpressler@cliftonnj.org","Apply: Standard certificate: call the office 7 business days after the inspection; inspections are on Wednesdays 9am to 12 noon. Faster certificates cost more (within 4 to 20 days, or within 4 business days).","How to apply: Fill out the Application for Dwelling Smoke Detector and Carbon Monoxide Compliance completely (check Sale), signed by both seller and buyer. Call the Building Department (973-470-5809) to make sure there are no open permits and ask when and where to get the application stamped. Bring the stamped application, the fee (payable to the City of Clifton) and, if digital signatures are not verified, a copy of the sales contract to Clifton Fire Headquarters (Yellow House on the City Hall property, 900 Clifton Avenue). After-hours drop-off is available in the Fire Headquarters drop box. Certificates must be picked up in person.","Valid for: 6 months after the Fire Department inspection","No open permits on the property (Building Department check and stamp on the application)","Tax and Zoning Department approval (the Zoning Officer reviews and approves all Dwelling Certificates)","Smoke alarms on every level (basement, each floor), excluding crawl spaces and unfinished attics with pull-down stairs","Smoke alarm within 10 feet of the bedroom doors on any floor with bedrooms","All smoke alarms less than 10 years old; battery-only alarms must be 10-year sealed battery units; existing hardwired systems must be kept","Carbon monoxide alarms within 10 feet outside all sleeping areas, with more on each floor that has sleeping areas","Central station fire alarm must be tested beforehand by a Division of Fire Safety certified company; bring the test record or the inspection fails","Multiple sources of power label within 18 inches of the electrical panel and meter for homes with a generator, solar or battery storage (the Bureau supplies and installs the label at the inspection)","An adult over 18 must be present and all areas (unit, basement, attic, common areas) must be accessible","Also: Open permits: Call the Building Department (973-470-5809) to make sure there are no open permits; the application needs the Building Department stamp.","Also: Tax and zoning sign-off: Certificates are contingent on passing the Building, Tax and Zoning Departments."]$j$::jsonb, $j$[{"label":"Dwelling certificate, sale, per unit (one certificate covers the town requirement and the smoke and carbon monoxide certificate; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit (paid instead of the standard fee)","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit (paid instead of the standard fee)","amount":"$300 per unit"},{"label":"Dwelling certificate (smoke and carbon monoxide compliance), sale, per unit (same certificate and fee as the town requirement; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit","amount":"$300 per unit"}]$j$::jsonb, $t$https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF$t$, $t$https://www.cliftonnj.org/174/Fire-Department$t$, $j$[{"url":"https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/242/Zoning","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/227/Building","label":"Official source (cliftonnj.org)"}]$j$::jsonb, $t$No closing shall take place without a VALID Certificate of Inspection. No tenant rental shall take occupancy without a VALID Certificate of Inspection. CERTIFICATES ARE CONTINGENT ON PASSING BUILDING, TAX & ZONING DEPTS.$t$, $t$5a15649f4b68e7747f0d58c8b21778e8008c3e04eefa54cc298c70da436d83ba$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1602.json$t$, true),
  ($t$1602$t$, $t$Clifton City$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Clifton Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Michael Pressler, Fire Marshal · (973) 470-5801 · mpressler@cliftonnj.org","Apply: Standard: certificate ready about 7 business days after the Wednesday inspection. Expedited options: within 4 to 20 days, or within 4 business days, at higher fees.","How to apply: Same application as the Dwelling Certificate: get the Building Department stamp, then bring the application and payment to Fire Headquarters (Yellow House, City Hall property, 900 Clifton Avenue) or use the after-hours drop box with a contact name and phone number on the envelope.","Fire official in the NJ state directory, updated 1/12/2026: Micahel K Pressler · (973) 470-5804 · MPressler@Cliftonnj.org","Smoke alarms on every level and within 10 feet of bedroom doors; all under 10 years old","Battery-only smoke alarms must be 10-year sealed battery units; existing hardwired systems must be maintained","CO alarms (UL 2034) within 10 feet outside all sleeping areas, on each floor with sleeping areas","Central station fire alarm test record from a Division of Fire Safety certified company is required at the inspection; inspectors will not test it","Multiple sources of power label for homes with a generator, solar or battery storage (supplied and installed by the Bureau at the inspection)","The City's Fire Department FAQ still says a dry chemical fire extinguisher, at least 10BC rated and no more than 10 pounds, is needed for the dwelling inspection; the May 2025 packet does not list one","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Dwelling certificate (smoke and carbon monoxide compliance), sale, per unit (same certificate and fee as the town requirement; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit","amount":"$300 per unit"}]$j$::jsonb, $t$https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF$t$, $t$https://www.cliftonnj.org/174/Fire-Department$t$, $j$[{"url":"https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/Faq.aspx?QID=110","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/174/Fire-Department","label":"Official source (cliftonnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION FOR DWELLING SMOKE DETECTOR & CARBON MONOXIDE COMPLIANCE ... THE CITY OF CLIFTON | 900 CLIFTON AVENUE, CLIFTON, NJ 07013 PHONE: 973-470-5801 | FAX: 973-470-5844$t$, $t$4c3cd5e650bfe6d735c2cc28f2ec09a93c965e71780f264e4c8598fbd5735cdc$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1602.json$t$, true),
  ($t$1609$t$, $t$Pompton Lakes Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), residential$t$, $j$["Issued by: Borough of Pompton Lakes Building Department (Construction Official), under Ordinance 91-30 (Borough Code Section 19-3)","Contact: Carmelina Fusaro, Assistant to Construction Official · 973-835-0143, ext. 223 · building@pomptonlakes-nj.gov","Apply: The Building Department page says to allow three weeks to complete the process; the application form says to allow a minimum of 5 business days for processing","How to apply: Complete the Residential CCO application (check Resale), sign it and submit it with a check payable to the Borough of Pompton Lakes to the Building Department, 25 Lenox Avenue. The office must have the completed application and fee before it schedules the inspection. Inspections are Tuesday through Friday, 3:30 to 5:30 pm. Contact the Fire Prevention Bureau separately for the smoke alarm and carbon monoxide alarm inspection.","Pressure relief (blow-off) pipe on the water heater and boiler must extend down to 6 inches above the floor","Grip-sized handrails on steps with 3 or more risers; no open stairways","Guardrails at least 36 inches high, with no more than 4 inches between balusters, on porches and landings more than 30 inches above grade","Visible house numbers on the house (not on doors)","Secure, firm and sealed chimney connection from the water heater, furnace, boiler or stove","No loose or unprotected electric wires or uncovered boxes","Sidewalks maintained by the homeowner to Borough Code","Separate smoke alarm, carbon monoxide alarm and fire extinguisher check by the Fire Prevention Bureau before resale","Someone 18 or older must be present at the inspection","Also: Zoning permit for change of use or tenant: The Building Department lists Change of Use / Tenant among projects needing zoning and/or construction permits; zoning is at ext. 241."]$j$::jsonb, $j$[{"label":"Residential Certificate of Continued Occupancy (application form)","amount":"$90.00"},{"label":"Residential Certificate of Continued Occupancy (ordinance Section 19-3.7 printed on the form)","amount":"$90.00"},{"label":"Additional follow-up inspections (one follow-up inspection is free)","amount":"$25.00"},{"label":"Each additional follow-up inspection after the free one (ordinance)","amount":"$25"},{"label":"Smoke/CO certificate, state schedule adopted as the Borough fee by Ordinance 23-23: Request received more than 10 business days before the change of occupant (N.J.A.C. 5:70-2.9(d))","amount":"$45.00"},{"label":"Smoke/CO certificate, state schedule adopted as the Borough fee by Ordinance 23-23: Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Smoke/CO certificate, state schedule adopted as the Borough fee by Ordinance 23-23: Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application$t$, $t$https://pomptonlakes-nj.gov/192/Building-Department$t$, $j$[{"url":"https://pomptonlakes-nj.gov/192/Building-Department","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/m/directory/department?did=21","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Continued Certificate of Occupancy (CCO) are required for the resale of residential homes and businesses as well as for change of tenancy. Forms may be obtained at the Building Department and appointments must be scheduled for the CCO Inspector to perform inspections. Please allow three weeks to complete the process.$t$, $t$a19c1a4c280596ae3f22d25b8f54de6502e5b47b613b7d7a13ef534bdb3c0d09$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1609.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1609.json$t$, true),
  ($t$1609$t$, $t$Pompton Lakes Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pompton Lakes Fire Prevention Bureau (Fire Official) (town fire bureau)","Contact: John Keating, Fire Official · 973-616-5918 · jkeating@pomptonlakes-nj.gov","Apply: Lowest fee when the request is received more than 10 business days before the change of occupant","How to apply: No application form or online portal is posted. Call the Fire Prevention Bureau at 973-616-5918 (the Borough says to call this number for inspections, permits, CO inspections and real estate closing issues) or email the Fire Official. Fees are payable to the Borough of Pompton Lakes.","Fire official in the NJ state directory, updated n/a: John F Keating · (973) 616-5918 · JKeating@pomptonlakes-nj.gov","The Borough's residential CCO form (2025) still lists a fire extinguisher with the smoke alarm and carbon monoxide alarm check by the Fire Prevention Bureau before resale or rental; the state removed the extinguisher from the state certificate in February 2025 (P.L.2025, c.19), so confirm with the Fire Prevention Bureau","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State schedule adopted as the Borough fee by Ordinance 23-23: Request received more than 10 business days before the change of occupant (N.J.A.C. 5:70-2.9(d))","amount":"$45.00"},{"label":"State schedule adopted as the Borough fee by Ordinance 23-23: Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"State schedule adopted as the Borough fee by Ordinance 23-23: Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, null, $t$https://pomptonlakes-nj.gov/155/Fire-Department$t$, $j$[{"url":"https://pomptonlakes-nj.gov/155/Fire-Department","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/m/directory/department?did=9","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.pomptonlakes-nj.gov/AgendaCenter/ViewFile/Item/651?fileID=27158","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Call 973-616-5918 for inspections, permits, CO inspections and Real Estate closing issues$t$, $t$9df4419e97ff39b7075430dcfb3036418d0b4dc7f9948f5ee8e8c6002d133abe$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1609.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1609.json$t$, true),
  ($t$1709$t$, $t$Pennsville Township$t$, $t$SALEM$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (Residential Resale housing inspection)$t$, $j$["Issued by: Housing Officer, Construction Code Office (Department of Code Enforcement / Bureau of Housing Inspections)","Contact: Dave Curry, Housing Officer · 856-678-3089 Ext: 1150 · housingofficer@pvtwp.com","Apply: No minimum stated. The fee must be paid in full before an inspection is scheduled; the clerk calls to set an appointment within 5 working days of payment.","How to apply: Fill in the Township of Pennsville Application for Continued Certificate of Occupancy, Residential Resale, and pay in full by certified check or money order payable to \"Township of Pennsville\" (or exact cash) at the Construction Code Office, 90 N Broadway. Applications can also be filed through the Township citizen portal (Apply for a Property Inspection, which needs a portal login). Inspections are Tuesday to Thursday, 3:00 to 5:30 PM.","Smoke alarms on every level, in each bedroom and within 10 feet outside each sleeping area (10-year sealed battery type)","Carbon monoxide alarm in the hallway within 10 feet of the bedrooms","Fire extinguisher 2A-10BC, under 10 pounds, mounted within 10 feet of the kitchen in plain sight, tagged or with a current receipt, top no higher than 5 feet","House numbers at least 4 inches and visible from the street","Handrails on stairs with 3 or more risers; guardrails with spindles no more than 4 inches apart on porches or decks 30 inches or higher","GFCI outlets within 6 feet of any water source or the breaker panel","Electric properly installed with no bare wires; heat working","Water heater working, at least 110 F, with the relief valve pipe extended to within 6 inches of the floor","Chimney certificate for fireplaces","Walls, ceilings and floors free of holes, chipped paint, cracks or stains; no rubbish inside or out","Doors and windows working with locks, screens on opening windows, one egress window in each sleeping area","Globe covers on closet and shelf lights; bathroom window or exhaust fan","Gutters, downspouts and roof sound; all plumbing working","Appliances working with an anti-tip bracket on the range; key locks on entry doors only","All utilities on at the inspection and no open construction permits","Also: Taxes, sewer and water current: No certificate of occupancy is issued unless Township taxes, sewer and water bills are current; for a change of ownership the Housing Officer may issue a conditional certificate with taxes paid by the settlement agent at closing.","Also: No open permits or violations: Documentation is needed that there are no outstanding open building permits, housing violations or court judgments barring occupancy; the resale form office section also checks open permits.","Also: As-is sale option: An \"As Is\" Document for Settlement (revised 11/14/22) lets the buyer take the home as-is, signed and notarized; the home must meet the property maintenance code before anyone occupies it."]$j$::jsonb, $j$[{"label":"Continued Certificate of Occupancy, residential resale (initial inspection)","amount":"$50"},{"label":"Housing Officer inspection, house for sale (ordinance)","amount":"$50.00"},{"label":"Re-inspection (office form)","amount":"$50"},{"label":"Second re-inspection (office form)","amount":"$50"},{"label":"Second or later inspection for the same certificate (ordinance; per house or unit)","amount":"$100.00"}]$j$::jsonb, $t$https://www.pennsville.org/DocumentCenter/View/472/Residential-Resale-PDF$t$, $t$https://www.pennsville.org/175/Construction-Code-Office$t$, $j$[{"url":"https://pennsvillenj.portal.fasttrackgov.com/","label":"Official source (pennsvillenj.portal.fasttrackgov.com)"},{"url":"https://www.pennsville.org/DocumentCenter/View/255/Chapter-07-Buildings-PDF","label":"Official source (pennsville.org)"},{"url":"https://www.pennsville.org/DocumentCenter/View/472/Residential-Resale-PDF","label":"Official source (pennsville.org)"},{"url":"https://www.pennsville.org/DocumentCenter/View/481/Minimum-CO-Requirements-For-Housing-Inspection-PDF","label":"Official source (pennsville.org)"},{"url":"https://www.pennsville.org/Directory.aspx?EID=23","label":"Official source (pennsville.org)"}]$j$::jsonb, $t$Apply for a Certificate of Continued Occupancy inspection. This inspection is required when residential property is sold or for changes in tenancy for residential rental properties.$t$, $t$834429aeaac946c73489107fc300781c1233a2743f9f49ee36fc96e914c3c6f2$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1709.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1709.json$t$, true),
  ($t$1709$t$, $t$Pennsville Township$t$, $t$SALEM$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pennsville Township Bureau of Fire Prevention and Inspections (town fire bureau)","Contact: Eric Guglielmo, Fire Administrator (Fire Official in the state fire directory) · 856-678-3089 ext. 1144 · pvfirecode@pvtwp.com","How to apply: Not published separately. Smoke alarm, CO alarm and extinguisher checks are part of the Township resale housing inspection (Continued Certificate of Occupancy). Ask the Construction Code Office or the Fire Administrator whether a separate smoke/CO certificate and fee apply.","Fire official in the NJ state directory (town), updated 5/19/2026: Eric Guglielmo · (856) 678-3089 · pvfireofficial@pvtwp.com","Township handout asks for 10-year sealed battery smoke alarms on each level, in each bedroom and within 10 feet outside each sleeping area","Carbon monoxide alarm in the hallway within 10 feet of the bedrooms","Township handout still lists a 2A-10BC fire extinguisher (under 10 pounds) mounted within 10 feet of the kitchen, tagged or with a current receipt, top no more than 5 feet above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.pennsville.org/221/Pennsville-Township-Fire-Department$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.pennsville.org/DocumentCenter/View/247/Chapter-14-Protection-Of-Life-And-Property-Doc-PDF","label":"Official source (pennsville.org)"},{"url":"https://www.pennsville.org/221/Pennsville-Township-Fire-Department","label":"Official source (pennsville.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.pennsville.org/DocumentCenter/View/481/Minimum-CO-Requirements-For-Housing-Inspection-PDF","label":"Official source (pennsville.org)"}]$j$::jsonb, $t$M Pennsville Township$t$, $t$7d38bd47de0b3cdc34021c771e33c1d2787bd929f7ccbb707d43ed0d86d8a168$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1709.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1709.json$t$, true),
  ($t$1714$t$, $t$Upper Pittsgrove Township$t$, $t$SALEM$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC), also called Certificate of Occupancy; Pre-Occupancy Inspection for sales$t$, $j$["Issued by: Zoning Office / Housing Office (Zoning & Housing Official)","Contact: Tanya Timberman, Zoning & Housing Official · 856-358-8500 · zoningofficer@upperpittsgrovenj.org","How to apply: Fill in the Upper Pittsgrove Township Pre-Occupancy Application, SALES Only (revised 03/30/2026) and mail it with a check payable to Upper Pittsgrove Township to the Township Housing Office, or leave it in the drop box at the Municipal Building, 431 Route 77, Elmer. The Smoke/CO certificate is a separate $25 application to the Bureau of Fire Prevention. Zoning Office hours are Tuesday 10 a.m. to 11:30 a.m.","House numbers 5 inches high and visible from the street","GFI protected outlets within 6 feet of a water source and on all exterior outlets","Fire extinguisher mounted in the kitchen","Appliances installed properly and working, no extension cords; exhaust fan over the stove (ductless hood allowed) and anti-tip bracket on the stove","Adequate electric, heating and plumbing service; two separate outlets in each habitable room","Bathroom vented or with a working window","Screened window in each room; all windows working with locks; exterior doors and hardware working","Handrails on steps with more than 3 risers; rails around landings or porches 30 inches or higher","Water heater relief valve piped to within 6 inches of the floor; emergency shut-off at the top of the stairs for a basement heater","Pools over 125 square feet and 3 feet or higher need a fence at least 4 feet high with a self-latching gate","House free of insect infestation","Smoke/CO inspection must pass (separate Bureau of Fire Prevention certificate)","Private well homes must comply with the Private Well Testing Act before sale; homes on a cesspool or privy cannot be sold until it is replaced with an approved system","Also: Private well testing: Under the Private Well Testing Act (N.J.S.A. 58:12A-26), a home on a private well cannot be sold without complying with the Act.","Also: Cesspool or privy: N.J.A.C. 7:9A-3.16 bars the sale of a property served by a cesspool, privy, outhouse or pit toilet until it is replaced with an approved system."]$j$::jsonb, $j$[{"label":"Pre-Occupancy Inspection, sales","amount":"$25"},{"label":"Re-inspection (if needed)","amount":"$25"}]$j$::jsonb, $t$https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf$t$, $t$https://upperpittsgrovenj.org/zoning-and-construction/$t$, $j$[{"url":"https://upperpittsgrovenj.org/zoning-and-construction/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/CO-Inspection-Checklist.pdf","label":"Official source (upperpittsgrovenj.org)"}]$j$::jsonb, $t$UPT ordinance requires a COC (Certificate of Compliance) on residential or commercial rental properties whenever occupants change; therefore, a new COC is also required prior to the sale of a property.$t$, $t$0a657e213b2f6aab939daeb33ae096b1dec7fc346e08b5be2ddb98a4a572b9d7$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1714.json$t$, true),
  ($t$1714$t$, $t$Upper Pittsgrove Township$t$, $t$SALEM$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Upper Pittsgrove Bureau of Fire Prevention (town fire bureau)","Contact: Tim O'Donnell, Fire & Safety Official and Smoke Detectors Inspector (Fire Official in the state fire directory) · 856-358-8500 · upperpittsgrovefm@outlook.com","Apply: Payment must be received before the inspection.","How to apply: Fill in the Township Certificate of Smoke/Carbon Monoxide Detector Compliance application and pay $25.00 by check or money order payable to the Upper Pittsgrove Bureau of Fire Prevention before the inspection. Questions go to upperpittsgrovefm@outlook.com or 856-358-8500.","Fire official in the NJ state directory (town), updated 4/7/2025: Timothy J O'Donnell · (856) 358-8500","10-year sealed battery smoke alarms on every level (or hardwired where required); basement alarm at the bottom of the stairwell at ceiling level","A 10-year sealed smoke alarm in every bedroom (Township rule); hardwired alarms cannot be replaced with battery alarms","Smoke and CO alarms must be less than 10 years old and working","CO alarm in the hallway within 10 feet of all bedrooms","A low-voltage fire alarm system must be tested and certified by an alarm contractor before the inspection; bring the certificate","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar, a generator or battery storage need a permanent printed label (for example \"Caution: Multiple Sources of Power\") at the main electrical panel and the electric meter","The Township CO checklist still lists a fire extinguisher mounted in the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke/Carbon Monoxide Detector Compliance inspection","amount":"$25.00"},{"label":"Re-inspection for a failed or no-show inspection (same as the initial inspection fee)","amount":"$25.00"}]$j$::jsonb, $t$https://upperpittsgrovenj.org/wp-content/uploads/2026/04/Smoke-and-CO-Application-Guidelines.pdf$t$, $t$https://upperpittsgrovenj.org/zoning-and-construction/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/04/Smoke-and-CO-Application-Guidelines.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/zoning-and-construction/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/emergency-services/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$M Upper Pittsgrove Township$t$, $t$a7f7a692982c7e4455b2f5a2c3df21dbd96fb492e233e4122b361163ddcf5af1$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1714.json$t$, true),
  ($t$2008$t$, $t$Kenilworth Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance / Certificate of Continued Occupancy (CCO), sale of property$t$, $j$["Issued by: Kenilworth Building Department (Construction Official / Zoning Official)","Contact: Anthony Monguso, Construction Official / Building Subcode Official / Zoning Official (also Code Enforcement Official) · 908-276-5802 · zoningofficer@kenilworthnj.org","How to apply: Fill out the Borough's Application for Certificate of Compliance (check Sale of Property) and file it with the Building Department at 567 Boulevard, Kenilworth. The Building Department takes cash or a check payable to Borough of Kenilworth.","Also: Open construction permits: The Building Department follows up on all open permits with Notices of Violations and, in some cases, penalties; schedule final inspections to close them."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy, residential (Ordinance 2026-11, adopted April 15, 2026; the old $175/$80 is struck out and replaced)","amount":"$200.00"},{"label":"Certificate of Continued Occupancy, residential reinspection (Ordinance 2026-11; the September 2026 application form instead shows $85.00 for each additional unit)","amount":"$85.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of single-family home, requested two or more weeks in advance (Ordinance 2026-08, which sets the sale fee equal to the annual inspection fee)","amount":"$100.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of two-family home, requested two or more weeks in advance (Ordinance 2026-08)","amount":"$160.00"},{"label":"Sale of single-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$150.00"},{"label":"Sale of two-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$210.00"}]$j$::jsonb, $t$https://www.kenilworthborough.com/DocumentCenter/View/120/Certificate-of-Compliance-Application-Form-SALE-OF-PROPERTY-CCO$t$, $t$https://www.kenilworthborough.com/183/Construction-Building-Department$t$, $j$[{"url":"https://www.kenilworthborough.com/184/Forms-Applications","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/120/Certificate-of-Compliance-Application-Form-SALE-OF-PROPERTY-CCO","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1604/2026-11-Ordinance-Amending-UCC-Fees-","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/400/FEE-CHANGES-2025","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/183/Construction-Building-Department","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1605/2026-08-Fire-Prevention-Inspection-Fees","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application","label":"Official source (kenilworthborough.com)"}]$j$::jsonb, $t$Certificate of Compliance Application Form (SALE OF PROPERTY, CCO)$t$, $t$a093757e360a76bda6c55044699d43a7227142439e87c3cecf2975e39839e956$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":2,"fee_bad":0,"fee_unchecked":8,"quotes":30,"q_ok":18,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/2008.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2008.json$t$, true),
  ($t$2008$t$, $t$Kenilworth Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Kenilworth Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Carmen Giordino, Fire Official (state fire directory) · (908) 276-8935 · cgiordino@kenilworthfire.org","Apply: The form's base fee is for a 1 week turnaround (higher fee if requested on less than 1 week); Ordinance 2026-08 sets the base sale fee for requests made two or more weeks in advance","How to apply: Download and print the Residential Fire Prevention application, then mail it or drop it in the white mailbox at Kenilworth Fire Headquarters, 491 Washington Ave, Kenilworth NJ 07033, with a check or money order (no cash) payable to Kenilworth Fire Prevention Bureau. The fire inspector calls to review requirements before the inspection.","Fire official in the NJ state directory, updated 1/27/2026: Carmen Giordino · (908) 276-8935 · cgiordino@kenilworthfire.org","Battery-only smoke and carbon monoxide alarms must be 10-year sealed battery units (since January 1, 2019), on each level and outside all bedroom areas","Hardwired (electric) smoke and CO alarms may not be replaced with battery alarms, and must be replaced after 10 years (date of manufacture is on the underside)","Electric CO alarms or combination smoke/CO alarms are required on each level and next to any fuel-burning appliance","Homes with a permanently installed generator, solar panels, battery storage or other secondary power source need a label (not handwritten) within 18 inches of the main electrical panel and the electric meter saying there are multiple power sources","The fire inspector contacts the applicant to review requirements before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide alarm inspection, sale of single-family home, requested two or more weeks in advance (Ordinance 2026-08, which sets the sale fee equal to the annual inspection fee)","amount":"$100.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of two-family home, requested two or more weeks in advance (Ordinance 2026-08)","amount":"$160.00"},{"label":"Sale of single-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$150.00"},{"label":"Sale of two-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$210.00"}]$j$::jsonb, $t$https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application$t$, $t$https://www.kenilworthborough.com/185/Fire-Department$t$, $j$[{"url":"https://www.kenilworthborough.com/185/Fire-Department","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1605/2026-08-Fire-Prevention-Inspection-Fees","label":"Official source (kenilworthborough.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.kenilworthborough.com/Directory.aspx?did=13","label":"Official source (kenilworthborough.com)"}]$j$::jsonb, $t$Smoke Detector Application Form: This form is used when there is a change of occupancy (sale or rental) for a single family, two-family, or rental apartment. This form must be download, printed, and mailed (along with the appropriate fee) to: Kenilworth Fire Department Attn: Bureau of Fire Prevention 491 Washington Avenue Kenilworth, NJ 07033$t$, $t$e9388fa444b1b3dd428deec65023f49474b2e8615ae21c75d02b994e02cc7d5a$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":2,"fee_bad":0,"fee_unchecked":8,"quotes":30,"q_ok":18,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/2008.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2008.json$t$, true),
  ($t$2009$t$, $t$Linden City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO), residential sale$t$, $j$["Issued by: Linden Health Department (residential Certificate of Occupancy inspections); the Construction Code office handles commercial CCOs","Contact: (908) 474-8409 · health@linden-nj.gov","How to apply: Apply online with the City's GovPilot 'Residential Sale CCO Application' (Residential Sale Only), linked from the City's Continued Certificate of Occupancy Application page. The form asks for the buyer, the agent and who to contact for inspections, and offers Pay Now or Submit & Pay Later. Questions go to the Health Department, 605 South Wood Avenue, (908) 474-8409.","Owner certifies the dwelling and all other structures meet the City's zoning requirements","No rubbish, debris or bulk garbage may be left on the property before the new occupancy"]$j$::jsonb, $j$[]$j$::jsonb, $t$https://main.govpilot.com/web/public/f18dd71d-989_CCO-Linden?uid=6947&ust=NJ&pu=1&id=0$t$, $t$https://linden-nj.gov/directory/health-department/$t$, $j$[{"url":"https://linden-nj.gov/documents/continued-certificate-of-occupancy-application/","label":"Official source (linden-nj.gov)"},{"url":"https://main.govpilot.com/web/public/f18dd71d-989_CCO-Linden?uid=6947&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://linden-nj.gov/directory/health-department/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/directory/construction-code/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf","label":"Official source (linden-nj.gov)"}]$j$::jsonb, $t$Click here for the Residential Sale CCO Application.$t$, $t$e75c36013c11fb03632e38751038a08c19496fbd41278f436ab8dcff028c2f7e$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":20,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2009.json$t$, true),
  ($t$2009$t$, $t$Linden City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Linden Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Christopher Rooney, Deputy Chief/Fire Official (the Fire Prevention page's email belongs to Fire Chief William M. Hasko, Jr.) · (908)-474-4560 · whasko@lindenfd-nj.gov","Apply: Apply more than 10 business days before the change of occupancy for the lowest fee. A new application is required if the sale does not happen within six months.","How to apply: Download the Smoke Detector & Carbon Monoxide Application Form from the City website, fill it out and mail it or drop it in the bin outside the Fire Prevention entrance, 302 South Wood Avenue, Monday to Friday 9 am to 5 pm. Checks payable to City of Linden (the under-4-business-days fee is cash only). The bureau schedules the inspection as soon as possible after it gets the application.","Fire official in the NJ state directory, updated 8/12/2025: Christopher D Rooney · (908) 474-4560 · crooney@lindenfs-nj.gov","Smoke alarms must be 10-year sealed battery or hardwired, on each level including basements (not attics or crawl spaces) and outside each separate sleeping area within 10 feet of the bedrooms","Carbon monoxide alarms outside each sleeping area","All alarms must work","Hardwired (A/C-powered) smoke alarms from the original construction may not be replaced with battery alarms","Homes with a secondary power source (generator, solar panels, battery storage) need a 'CAUTION: MULTIPLE SOURCES OF POWER' label (not handwritten) within 18 inches of the main electrical panel and the electric meter","A property representative or homeowner must be present at the inspection; a no-show counts as a failure","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke detector and carbon monoxide alarm compliance, request received more than 10 business days before the change of occupancy","amount":"$50.00"},{"label":"Certificate, request received 4 to 10 business days before the change of occupancy","amount":"$90.00"},{"label":"Certificate, request received fewer than 4 business days before the change of occupancy (cash only)","amount":"$170.00"}]$j$::jsonb, $t$https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf$t$, $t$https://linden-nj.gov/directory/fire-prevention/$t$, $j$[{"url":"https://linden-nj.gov/directory/fire-prevention/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/document-category/fire-prevention/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf","label":"Official source (linden-nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Fire Prevention Department reports to the Fire Chief and provides inspection of business and home locations to insure fire prevention safety and Smoke Detector, Carbon Monoxide and Fire Extinguisher Inspections for building and home sales in accordance with the New Jersey State Uniform Fire Codes.$t$, $t$a5f631ff753bb40ad1757d951da0592b5bf4a713678a45dfae5a2574eb16679b$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":20,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2009.json$t$, true),
  ($t$2012$t$, $t$Plainfield City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (sale)$t$, $j$["Issued by: City of Plainfield Division of Inspections, Property Maintenance Unit (Department of Public Works and Urban Development)","Contact: Athenee Wright, General assistance, Inspections-Property Maintenance Unit (Spanish: Stephanie Hidalgo-Mendez, 908-753-2526… · 908-753-3384 · athenee.wright@plainfieldnj.gov","Apply: Schedule the inspection before closing; inspections are 10 am to 12:30 pm and someone must be there to let the inspector in","How to apply: Complete the Certificate of Compliance for Sale Application (on the City's Get a Permit or License page, Inspections Division forms) and schedule an inspection before closing. Submit it to the Division of Inspections, 515 Watchung Avenue. The application asks about the property, legal occupancy, buyer, closing date, permits and smoke/CO detectors. An LLC applicant must also give its Certificate of Formation. To close on a temporary certificate, the buyer signs a notarized affidavit and $500 per unit escrow is posted by certified check or money order.","Exterior walls, roofs, porches, stairs, railings and accessory structures","Yards, driveways, vegetation, trash and abandoned vehicles","Kitchens, bathrooms, bedrooms and other habitable rooms","Basements, cellars and crawlspaces","Common hallways, stairs and exits","Plumbing, water and hot water service; heating equipment and required temperatures","Electrical fixtures, switches and outlets","Smoke and carbon monoxide detectors","Windows, doors, walls, ceilings and floors; signs of leaks, moisture, vermin or unsafe conditions","Legal number of units and occupancy matching zoning and construction records","Open permits or work that looks like it was done without permits","Heating system / heating unit certificate on the licensed certifier's letterhead with license number","Smoke detector, carbon monoxide and fire extinguisher certificate from the Fire Division","For 3 or more units, a current Certificate of Inspection from the NJ Bureau of Housing Inspection","Also: Heating system certification: A heating system / heating unit certificate on the licensed certifier's letterhead with license number is required for the Certificate of Compliance.","Also: Multiple dwellings: For 3 or more units, a current Certificate of Inspection from the NJ Bureau of Housing Inspection.","Also: Open permits: Permits needed for work found during inspection must be obtained and inspected by the subcode officials before a clear certificate."]$j$::jsonb, $j$[{"label":"Certificate of Compliance for sale, first residential unit","amount":"$50"},{"label":"Each additional residential unit at the same property","amount":"$25"},{"label":"Missed appointment or no-show fee","amount":"$25"},{"label":"Certificate of Compliance exemption application","amount":"$75"},{"label":"Escrow when closing with a temporary Certificate of Compliance, per unit","amount":"$500"},{"label":"One family, application received 11+ business days before the inspection","amount":"$45"},{"label":"One family, application received 4 to 10 business days before the inspection","amount":"$90"},{"label":"One family, expedited, 1 to 3 business days before the inspection","amount":"$161"},{"label":"One family, reinspection on the next available Wednesday","amount":"$45"},{"label":"Two family, application received 11+ business days before the inspection","amount":"$90"},{"label":"Two family, application received 4 to 10 business days before the inspection","amount":"$180"},{"label":"Two family, expedited inspection, application received 1 to 3 business days before","amount":"$322"},{"label":"Two family, reinspection on the next Wednesday","amount":"$90"},{"label":"Returned check charge","amount":"$20.00"}]$j$::jsonb, $t$https://www.plainfieldnj.gov/C%20OF%20C%20SALE%20APPLICATION.12.22.docx$t$, $t$https://www.plainfieldnj.gov/residents/household/code_enforcement_and_inspections_division/index.php$t$, $j$[{"url":"https://www.plainfieldnj.gov/residents/household/code_enforcement_and_inspections_division/index.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.plainfieldnj.gov/C%20OF%20C%20SALE%20APPLICATION.12.22.docx","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.plainfieldnj.gov/residents/get_a_permit_or_license.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.govpaynow.com/gps/user/cyg/plc/a0045L","label":"Official source (govpaynow.com)"},{"url":"https://www.plainfieldnj.gov/Document_Center/Applications%20Documents/Fire/ApplicationforInspectionCertificationofSmokeAlarm.Revised12.2021.pdf","label":"Official source (plainfieldnj.gov)"}]$j$::jsonb, $t$For a sale or rental, the City verifies compliance through a Certificate of Compliance inspection conducted by the Property Maintenance Unit.$t$, $t$46b62e7be5db0835633b599728b90d7d03efe162fcf2c8dd4b6d1d8cd4dc27e3$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":23,"fee_ok":23,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":19,"q_bad":4,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2012.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2012.json$t$, true),
  ($t$2012$t$, $t$Plainfield City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Plainfield Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Anthony Pineda, Fire Official (state fire directory, survey July 2026); Fire Prevention is headed by Deputy Chief Joseph Franklin… · (908) 753-3446 · fireinspection@plainfieldnj.gov","Apply: Pay 11 or more business days before the inspection for the lowest fee. Inspections are on Wednesdays. A failed or missed inspection needs a new application and full payment.","How to apply: Pay online through the City's 'Smoke Home Inspections' GovPayNow page (card or e-check; a processing fee applies) or fill out the Application for Inspection Certification of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance and e-mail it to fireinspection@plainfieldnj.gov. Then call (908) 753-3446 to confirm payment; the bureau e-mails the inspection date. By mail or in person, checks are payable to Plainfield Fire Department (personal checks only for the $45.00 fee).","Fire official in the NJ state directory, updated 7/22/2026: Anthony Pineda · (908) 753-3446 · anthony.pineda@plainfieldnj.gov","Smoke alarm on each level including basements (not attics unless finished, or crawl spaces)","Smoke alarm and carbon monoxide alarm near any flame-producing device, outside each sleeping area and within 10 feet of all bedroom doors","Battery-only smoke alarms must be 10-year sealed battery type; combination smoke/CO 10-year sealed alarms are acceptable","Homes with a low-voltage alarm system need an alarm test report from a NJ certified fire protection contractor","Portable fire extinguisher (2A:10BC, no more than 10 pounds) in the kitchen, no more than 5 feet above the floor, new with receipt or serviced and tagged within 12 months (2021 form; the City payment notice still names the extinguisher certificate)","Only one- and two-family dwellings are inspected; inspections are on Wednesdays","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"One family, application received 11+ business days before the inspection","amount":"$45"},{"label":"One family, application received 4 to 10 business days before the inspection","amount":"$90"},{"label":"One family, expedited, 1 to 3 business days before the inspection","amount":"$161"},{"label":"One family, reinspection on the next available Wednesday","amount":"$45"},{"label":"Two family, application received 11+ business days before the inspection","amount":"$90"},{"label":"Two family, application received 4 to 10 business days before the inspection","amount":"$180"},{"label":"Two family, expedited inspection, application received 1 to 3 business days before","amount":"$322"},{"label":"Two family, reinspection on the next Wednesday","amount":"$90"},{"label":"Returned check charge","amount":"$20.00"}]$j$::jsonb, $t$https://www.govpaynow.com/gps/user/cyg/plc/a0045L$t$, $t$https://www.plainfieldnj.gov/departments/fire/index.php$t$, $j$[{"url":"https://www.plainfieldnj.gov/departments/fire/index.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.govpaynow.com/gps/user/cyg/plc/a0045L","label":"Official source (govpaynow.com)"},{"url":"https://www.plainfieldnj.gov/Document_Center/Applications%20Documents/Fire/ApplicationforInspectionCertificationofSmokeAlarm.Revised12.2021.pdf","label":"Official source (plainfieldnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention - Deputy Chief Joseph Franklin$t$, $t$9c7a0221f8586aaec769a10107127b31a27cfdf04e8ece7ed6e6a1d1b21a3f1d$t$, $t$2026-10-06T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-06","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":23,"fee_ok":23,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":19,"q_bad":4,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2012.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-06 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2012.json$t$, true)
